"Das Engine-Logo ist davon ausgenommen: Es lässt sich immer erst nach 2 Sekunden überspringen.": "エンジンのロゴは例外で、2秒後からしかスキップできません。",
"Das Ergebnis wird aus dem Seed des Durchlaufs und der ID der Quelle berechnet. Zurückladen bringt dieselbe Beute, ein neues Spiel neue.": "結果はプレイのシード値と入手元のIDから計算されます。ロードし直しても同じ戦利品、新しいゲームなら別の戦利品です。",
"Das Gebäude erscheint erst, wenn irgendwo die Aktion „🏰 Gebäude freischalten“ ausgeführt wird – am einfachsten per Rechtsklick auf ein Hub-Objekt → Bausteine → „Wird gekauft …“.": "建物はどこかでアクション「🏰 建物を解放」が実行されて初めて表示されます。一番簡単なのはハブオブジェクトを右クリック → ブロック → 「購入できる …」。",
"Das Gebäude ist auf „Durch Aktion“ gestellt, aber keine Aktion „🏰 Gebäude freischalten“ zeigt darauf. Spieler bekommen es nie.": "建物は「アクションで」に設定されていますが、それを指す「🏰 建物を解放」アクションがありません。プレイヤーは決して入手できません。",
"Das Grundgerüst (Programm und Browser-Technik) ist bei jedem Windows-Spiel gleich groß, auch bei einem winzigen Spiel. Beim Web-Spiel übernimmt das der Browser.": "基本部分(プログラムとブラウザ技術)はどんなに小さなWindowsゲームでも同じサイズです。Webゲームではブラウザがそれを担います。",
"Das Inventar hat eigene Bilder für Fenster und Plätze:": "インベントリにはウィンドウとスロット用の画像があります:",
"Das Original wurde geändert, seit übersetzt wurde": "翻訳後に原文が変更されました",
"Das Spiel beginnt hier": "ゲームはここから始まります",
"Das Spiel bleibt bei dieser Zeile stehen, bis der Spieler etwas getan hat – z. B. das Inventar geöffnet oder etwas angezogen. Gut für Tutorials im eigenen Spiel.": "プレイヤーが何かをするまで(例: インベントリを開く、何かを装備する)ゲームはこの行で止まります。自作ゲームのチュートリアルに便利です。",
"Das Spiel lädt nur die Plugins, die du mitlieferst – unverändert. Fremde oder veränderte Dateien werden ignoriert.": "ゲームは同梱したプラグインだけを変更なしで読み込みます。他人のファイルや変更されたファイルは無視されます。",
"Das Spielsystem „Ausrüstung“ ist aus – unter Spielsysteme → Übersicht einschalten.": "ゲームシステム「装備」はオフです。ゲームシステム → 概要でオンにしてください。",
"Das Sprecher-Skript listet alle Zeilen pro Figur mit ID, damit die Aufnahmen richtig benannt werden.": "話者台本はキャラクターごとに全セリフをIDつきで並べ、録音に正しい名前を付けられるようにします。",
"Das Update wird im Hintergrund geladen. Du kannst dabei weiterarbeiten.": "アップデートはバックグラウンドでダウンロードされます。作業を続けられます。",
"Das aktuelle Ziel dauert länger als geplant – alles läuft schneller.": "現在の目標が予定より長くかかっています — すべてが速くなります。",
"Das ergibt nur Matsch.": "それではドロドロになるだけ。",
"Das funktioniert hier nicht.": "ここではうまくいきません。",
"Das gehört dir schon.": "それはもうあなたのものです。",
"Das gleiche Geschenk wirkt jedes Mal nur halb so stark": "同じプレゼントは毎回効果が半分になります",
"Das ist eine Beispielzeile, damit du siehst, wie die Sprechblase im Spiel wirkt.": "これはゲーム内の吹き出しの見た目を確認するためのサンプル行です。",
"Das ist kein Deckel: Im Spiel steigt der Wert immer bis 100 %. Es fehlen nur noch Stellen, an denen es Punkte gibt. Während du baust, ist das normal.": "これは上限ではありません。ゲーム内では値は常に100%まで上がります。まだポイントをもらえる場所が足りないだけで、制作中は普通のことです。",
"Das kann man hier nicht benutzen.": "ここでは使えません。",
"Das passende System ist gerade aus": "対応するシステムは現在オフです",
"Das passt nicht zusammen.": "それは組み合わせられません。",
