"Den Keller betreten": "地下室に入る",
"Der Antwort ein Ziel geben.": "回答に行き先を設定してください。",
"Der Dietrich ist abgerutscht …": "ピックが滑った …",
"Der Filter färbt Hintergrund und Figuren um. „Rückblende“ bringt Sepia und weiche, helle Ränder mit.": "フィルターは背景とキャラクターの色を変えます。「回想」はセピアと柔らかく明るい縁を加えます。",
"Der Klickpunkt ist die Stelle im Bild, die genau auf das Ziel zeigt, z. B. die Spitze eines Pfeils. Fahre über die Vorschau, um den Zeiger zu sehen.": "クリック位置は画像の中で正確に対象を指す点です(例: 矢印の先)。プレビューにマウスを乗せるとカーソルを確認できます。",
"Der Laden ist leer.": "ショップは空です。",
"Der Spieler klickt das Objekt an, bestätigt den Kauf, das Geld wird abgezogen und es passiert, was du hier wählst. Ohne Variablen, ohne Bedingungen.": "プレイヤーがオブジェクトをクリックし、購入を確認すると、お金が引かれ、ここで選んだことが起こります。変数も条件も不要です。",
"Der Windows-Export funktioniert nur in der fertigen Programmversion (.exe).": "Windowsへのエクスポートは完成版プログラム(.exe)でのみ動作します。",
"Der verlorene Schlüssel": "失われた鍵",
"Design · Auswahl": "デザイン · 選択肢",
"Design · Figur": "デザイン · キャラクター",
"Design · Hintergrund": "デザイン · 背景",
"Design · Hub-Hintergrund": "デザイン · ハブ背景",
"Design · Hub-Objekt": "デザイン · ハブオブジェクト",
