"Dialoge ab Schritt": "ステップからのセリフ",
"Dialoge, Ren'Py": "セリフ、Ren'Py",
"Die 10 größten Dateien": "大きいファイル トップ10",
"Die Antwort steht im letzten Schritt der Szene und die Szene hat kein „Danach weiter zu“. Wählt der Spieler sie, ist das Spiel zu Ende.": "回答はシーンの最後のステップにあり、シーンに「その後の行き先」がありません。プレイヤーが選ぶとゲームが終わります。",
"Die Aufnahme ist leer geblieben.": "録音は空でした。",
"Die Ausrüstung erscheint oben im Inventar (Taste I). Ein Klick auf einen belegten Platz legt den Gegenstand ab. Gibt der Spieler einen getragenen Gegenstand ab, wird er automatisch abgelegt.": "装備はインベントリ(Iキー)の上部に表示されます。埋まったスロットをクリックすると外します。装備中のアイテムを手放すと自動で外れます。",
"Die Bühne im Editor ist genau so groß wie später das Spiel. Du kannst das später beim Exportieren noch ändern.": "エディターのステージは後のゲームとまったく同じ大きさです。エクスポート時にまだ変更できます。",
"Die Datei konnte nicht gelesen werden.": "ファイルを読み込めませんでした。",
"Die Engine hat erkannt, dass ein Objekt genau diesen Umweg benutzt.": "エンジンは、あるオブジェクトがまさにこの回避策を使っていることに気づきました。",
"Die Engine kann sie nicht prüfen. Im Spiel gilt sie deshalb als nicht erfüllt, und was daran hängt, erscheint nie.": "エンジンはこれを確認できません。ゲーム内では未達成として扱われるため、それに依存するものは表示されません。",
"Die Engine prüft jedes eingeschaltete System, ob es so im Spiel funktionieren kann.": "エンジンは有効な各システムがゲーム内でこのまま動くかを確認します。",
"Die Engine sucht im ganzen Projekt nach der passenden Aktion.": "エンジンはプロジェクト全体から対応するアクションを探します。",
"Die Engine verfolgt alle Wege ab der Startszene. Kommt sie nirgends bei dieser Szene an, erscheint die Meldung.": "エンジンは開始シーンからすべてのルートをたどります。どれもこのシーンに届かないと、このメッセージが表示されます。",
"Die Engine zählt alle ♥-Punkte zusammen, die eine Figur im ganzen Spiel bekommen kann – Startwert plus jede Stelle, an der es Punkte gibt. Liegt eine Stufe mit Belohnung darüber, kann kein Spieler sie erreichen.": "エンジンはキャラクターがゲーム全体で得られる♥ポイント(初期値+ポイントがもらえる全箇所)を合計します。報酬つきの段階がそれより高いと、誰も到達できません。",
"Die Figur wird über ihren Namen erkannt (Sprecher = Name der Figur am Clip oder Dateiname).": "キャラクターは名前で認識されます(話者 = クリップ上のキャラクター名かファイル名)。",
"Die Kamera bewegt die ganze Bühne: Hintergrund, Figuren und Effekte. Dialog und Buttons bleiben stehen. Mit Parallax-Ebenen (am Hintergrund) entsteht Tiefe.": "カメラはステージ全体(背景、キャラクター、効果)を動かします。セリフとボタンは固定です。視差レイヤー(背景)で奥行きが出ます。",
"Die Spielzeit läuft in Tageszeiten. Sie ändert sich nur durch die Aktion „Zeit vergehen lassen“ (z. B. nach einem Job oder beim Schlafen). Prüfen kannst du sie mit der Bedingung „Zeit / Kalender“.": "ゲーム内時間は時間帯ごとに進みます。アクション「時間を進める」でのみ変わります(例: 仕事の後や睡眠時)。条件「時間 / カレンダー」で確認します。",
"Die Stelle ist gerade nicht sichtbar – vielleicht erst den richtigen Bereich öffnen.": "その場所は今は見えません — まず該当するエリアを開いてください。",
"Die Szene auswählen.": "シーンを選択します。",
"Die Truhe öffnen": "宝箱を開ける",
"Die Vorlage legt ein passendes Skelett über die Figur. Danach ziehst du die Gelenke an die richtigen Stellen und ergänzt Haare, Flügel oder einen Schweif als Kette.": "テンプレートが合う骨格をキャラクターに配置します。その後、関節を正しい位置へドラッグし、髪・翼・しっぽをチェーンとして追加します。",
"Die Vorschau benutzt Bilder aus deinem Projekt, damit du sofort siehst, wie es im Spiel wirkt.": "プレビューはプロジェクトの画像を使うので、ゲームでの見た目がすぐわかります。",
"Die Wache bestechen (50 Gold)": "衛兵を買収する(50ゴールド)",
"Die Wolken stehen still. Das ändern wir!": "雲が止まっています。動かしましょう!",
