"Doppelklick öffnet eine Szene. Rechtsklick auf eine Szene oder eine Linienbeschriftung für neue Pfade.": "ダブルクリックでシーンを開きます。シーンや線のラベルを右クリックで新しいルート。",
"Doppelklick: Farb-/Licht-Ebene · Partikel und Filter aus „Effekte“ links hierher ziehen": "ダブルクリック: 色/光レイヤー · 左の「効果」からパーティクルとフィルターをここへドラッグ",
"Doppelklick: Kamerafahrt (Zoom, Schwenk, Wackeln) · Vorlagen aus „Effekte“ links": "ダブルクリック: カメラ移動(ズーム、パン、揺れ)· 左の「効果」からテンプレート",
