"Drei Arten: Idle (Dauer-Schleife einer Figur), Geste (einmalig, z. B. Winken) und Zwischensequenz mit Hintergrund, mehreren Figuren, Kamera und Ton.": "3種類: 待機(キャラクターのループ)、ジェスチャー(1回、例: 手を振る)、背景・複数キャラ・カメラ・音つきのカットシーン。",
"Drei Stellen: Hier Figuren einschalten. In jeder Antwort steht ein Feld „♥ Beziehung“ (+10 Ray). Und überall unter „Nur wenn“ gibt es „♥ Beziehung … ab Stufe Freund“. Den Bildschirm „Beziehungen“ öffnet der Spieler mit Taste B oder im Pausenmenü.": "3か所: ここでキャラクターをオンにします。各回答には「♥ 関係」欄(+10 Ray)があります。「表示条件」には必ず「♥ 関係 … 段階:友達から」があります。プレイヤーはBキーかポーズメニューで「関係」画面を開きます。",
