"Ebenen von unten nach oben. Alle Bilder einer Figur sollten gleich groß sein (gleiche Leinwand), damit sie genau übereinander passen.": "レイヤーは下から上へ。キャラクターのすべての画像は同じサイズ(同じキャンバス)にすると、ぴったり重なります。",
