"Eigene Bilder (z. B. ein PNG mit Feuerball) erscheinen kurz groß über dem Ziel. So lassen sich alle Effekte austauschen.": "自分の画像(例: 火の玉のPNG)が対象の上に一瞬大きく表示されます。これでどんな効果も差し替えられます。",
"Eigene Inhalte legst du unter Spielsysteme": "独自の内容はゲームシステムで作成",
