"Eigene Punkte (z. B. Skillpunkte, Ruhm, Talentpunkte)": "独自ポイント(例: スキルポイント、名声、才能ポイント)",
"Eigene Schriften": "独自フォント",
"Eigene Schriften werden beim Export mitgepackt. Achte darauf, dass die Lizenz der Schrift die Weitergabe in Spielen erlaubt.": "独自フォントはエクスポートに含まれます。ゲームでの配布がライセンスで許可されているか確認してください。",
