"Eigenes Schwarz-Weiß-Bild": "独自の白黒画像",
"Eigenschaften": "プロパティ",
"Ein Bild wird automatisch zerschnitten und gemischt. Ohne eigenes Bild nimmt es den aktuellen Hintergrund.": "画像が自動で切り分けられて混ぜられます。独自画像がなければ現在の背景を使います。",
"Ein Dietrich könnte helfen.": "ピッキングツールが役に立つかも。",
"Ein Gebäude erst nach einem gewonnenen Kampf freischalten.": "バトルに勝って初めて建物を解放。",
"Ein Gegner": "敵1体",
"Ein Haus kaufen, das danach als neuer Ort auf der Karte erscheint.": "家を買うと、マップに新しい場所として現れる。",
"Ein Händler, bei dem man einmalig eine Schatzkarte kaufen kann.": "宝の地図を一度だけ売る商人。",
"Ein Keyframe legt fest, wohin sich das Objekt bewegt, wenn der Spieler diesen Schritt erreicht. Die Kurve bestimmt, wie weich es dort ankommt.": "キーフレームは、プレイヤーがこのステップに来たときオブジェクトがどこへ動くかを決めます。カーブで到着の滑らかさが決まります。",
"Ein Ort, an dem der Spieler frei klickt. Bilder aus der Dateiliste auf die Bühne ziehen, um klickbare Objekte anzulegen.": "プレイヤーが自由にクリックできる場所。ファイルリストから画像をステージにドラッグすると、クリックできるオブジェクトになります。",
"Ein Projekt ist ein Ordner mit einer": "プロジェクトとは次を含むフォルダーです:",
"Ein Stammgast lässt Trinkgeld da.": "常連客がチップをくれた。",
"Ein Stift dreht sich im Schloss. Klicke (oder drücke Leertaste), wenn er im goldenen Bereich ist. Das Ergebnis landet in einer Variable.": "錠前の中でピンが回ります。金色のゾーンにあるときにクリック(またはスペース)。結果は変数に入ります。",
"Ein Verbündeter": "味方1人",
"Ein Ziel ist in 10 Stunden nicht erreichbar: Kosten, Produktion oder Freischaltung prüfen (ohne Klicken, ohne Skilltrees gerechnet).": "ある目標に10時間以内に到達できません: コスト、生産、解放を確認してください(クリックなし、スキルツリーなしで計算)。",
"Ein-/Ausblenden": "フェードイン/アウト",
"Einblenden": "フェードイン",
"Einblendung bei Änderung": "変化時に通知",
"Einblendung zeigen (aus = Beziehungen bleiben geheim)": "通知を表示(オフ = 関係は秘密のまま)",
"Einblendungen im Spiel": "ゲーム内の通知",
"Eine Antwort, ein Hub-Objekt oder „Danach weiter zu“ auf diese Szene zeigen lassen.": "回答、ハブオブジェクト、または「その後の行き先」をこのシーンに向けてください。",
"Eine Datei fehlt": "ファイルが1つありません",
"Eine Ebene kann einer Variable folgen: Hat die Variante einen passenden „Wert“, wird sie automatisch gewählt (z. B. Outfit = 2 → Rüstung).": "レイヤーは変数に従えます。バリエーションの「値」が一致すると自動で選ばれます(例: 衣装 = 2 → 鎧)。",
"Eine Ebene über den Figuren: Farbe oder Bild mit Mischmodus, Partikel (Regen, Schnee …), ein Filter wie „Rückblende“ oder Augen öffnen/schließen. Fertige Effekte findest du links unter „Effekte“.": "キャラクターの上のレイヤー: 合成モードつきの色や画像、パーティクル(雨、雪 …)、「回想」などのフィルター、目の開閉。既製の効果は左の「効果」にあります。",
"Eine Fähigkeit mit eigenem Ton spielt diesen statt der Standardtöne.": "独自の効果音を持つアビリティは、既定の音の代わりにそれを再生します。",
"Eine Spalte = ein Klick des Spielers": "1列 = プレイヤーの1クリック",
"Eine Story-Szene, die startet, wenn man an den Ort kommt und die Bedingungen passen. Pflicht-Ereignisse kommen zuerst (z. B. „Tag 5, morgens, Zuhause → Brief vom König“). Am Ende der Szene „Danach weiter zu“ leer lassen oder „↩ Zurück zum Ort“ wählen.": "場所に到着し条件が合うと始まるストーリーシーン。必須イベントが優先されます(例:「5日目、朝、自宅 → 王からの手紙」)。シーンの最後は「その後の行き先」を空にするか「↩ 場所に戻る」を選びます。",
"Eine Wiederholung spielt nur diese Szene und kehrt danach zur Galerie zurück. Spielstand und Werte bleiben unberührt.": "リプレイはこのシーンだけを再生し、その後ギャラリーに戻ります。セーブデータと値は変わりません。",
"Eine lange Aufnahme mit vielen Sätzen? „Schneiden“ → „Teile erkennen“ → automatisch auf die Dialoge verteilen.": "多くの文を含む長い録音? 「カット」→「部分を検出」→ セリフに自動で割り当て。",
"Eine neuere Version dieses mitgelieferten Plugins ist da. Du hast die Datei selbst geändert – beim Einspielen gehen deine Änderungen verloren.": "この同梱プラグインの新しいバージョンがあります。ファイルを自分で変更したため、インストールすると変更は失われます。",
"Eine „Nur wenn“-Bedingung verweist auf etwas, das es nicht mehr gibt – z. B. eine gelöschte Variable, Figur oder einen Gegenstand.": "「表示条件」が、もう存在しないもの(削除した変数、キャラクター、アイテムなど)を参照しています。",
