"Erfolge schalten sich frei, wenn ihre Bedingung erfüllt ist (z. B. „Szene ‚Gutes Ende‘ gesehen“), oder per Aktion „🏆 Erfolg freischalten“. Sie gelten für alle Spielstände. Spieler sehen sie im Hauptmenü (Knopf mit Aktion „Erfolge“) und im Pausenmenü.": "実績は条件を満たすと(例:「シーン『グッドエンド』を見た」)、またはアクション「🏆 実績を解除」で解除されます。すべてのセーブデータで共通です。プレイヤーはメインメニュー(アクション「実績」のボタン)とポーズメニューで確認できます。",
"Erfolge öffnen": "実績を開く",
"Ergebnis": "結果",
