"Erklärung …": "説明 …",
"Erledigt": "完了",
"Erledigt! Klicken zum Weiterlesen.": "完了!クリックで続行。",
"Erledigt, wenn": "完了条件",
"Erledigt, wenn (ohne Abschnitte)": "完了条件(セクションなし)",
"Erreicht die Beziehung den Wert, schickt die Figur eine Nachricht – auf Wunsch mit Bild. Das Bild landet in der Galerie bei dieser Figur und leuchtet dort als „Neu“, bis man es ansieht. Aussehen und Töne: Design → Spielsysteme → „Nachricht einer Figur“.": "関係が値に達すると、キャラクターがメッセージを送ります(画像つきも可)。画像はこのキャラクターとしてギャラリーに入り、見るまで「NEW」と光ります。見た目と音: デザイン → ゲームシステム →「キャラクターからのメッセージ」。",
"Erreicht, wenn": "達成条件",
"Erscheint, nachdem der Dialog dieses Schritts gelesen wurde. Ohne Ziel geht es in dieser Szene weiter.": "このステップのセリフを読んだ後に表示されます。行き先がなければシーンが続きます。",
"Erscheint, wenn eine Entscheidung die Zuneigung ändert: Name, Leiste vom alten zum neuen Wert, Pfeil mit Zahl und auf Wunsch das Porträt (aus der Figur oben). Stufenwechsel bekommen eine größere Einblendung.": "選択で好感度が変わると表示: 名前、旧値から新値へのバー、数値つきの矢印、必要なら(上のキャラクターの)ポートレート。段階の変化はより大きく通知されます。",
"Erschrecken": "びっくり",
"Ersetzt die Keyframes der betroffenen Knochen.": "対象ボーンのキーフレームを置き換えます。",
"Erst aus, dann ein": "先にオフ、その後オン",
"Erst baubar, wenn (optional)": "建設できる条件(任意)",
"Erst eine Story-Szene öffnen": "まずストーリーシーンを開いてください",
"Erst einen Knochen anklicken": "まずボーンをクリックしてください",
"Erst später in der Geschichte": "ストーリーの後半で",
