"Exportierte Vorlagen lassen sich in andere Projekte laden. Eigene Bilder (Rahmen, Pfeil) muss man dort neu wählen.": "エクスポートしたテンプレートは他のプロジェクトで読み込めます。独自の画像(枠、矢印)はそこで選び直す必要があります。",
