"Fertige Bewegungen wie Laufen, Nicken, Winken oder Flügelschlag, Posen speichern und spiegeln, und Zwischensequenzen live einfügen oder als Video rendern.": "歩く、うなずく、手を振る、羽ばたきなどの既製の動き。ポーズの保存と反転、カットシーンをライブで挿入または動画として書き出し。",
"Fertige Dialoge als Text einfügen (auch Ren'Py)": "完成したセリフをテキストで挿入(Ren'Pyも可)",
"Fertige Dialoge einfügen: eine Zeile pro Satz als „Name: Text“, Zeilen ohne Namen sind Erzähler. „> Antwort“ untereinander wird eine Auswahl, „# Titel“ beginnt eine neue Szene. Ren'Py-Skripte werden erkannt (Sprecher-Kürzel aus „define“, menu, label); Bilder, Musik und Sprünge werden übersprungen.": "完成したセリフを挿入: 1文1行で「名前: テキスト」、名前のない行はナレーション。連続する「> 回答」行は選択肢になり、「# タイトル」で新しいシーンが始まります。Ren'Pyスクリプトも認識(「define」の話者コード、menu、label、jump)。画像と音楽はスキップ。",
"Fertige Dialoge einfügen: eine Zeile pro Satz als „Name: Text“, Zeilen ohne Namen sind Erzähler. „> Antwort“ untereinander wird eine Auswahl, „# Titel“ beginnt eine neue Szene. Ren'Py-Skripte werden erkannt (Sprecher-Kürzel aus „define“, menu, label); Sprünge (jump) werden zu Verbindungen, Bilder und Musik werden übersprungen.": "完成したセリフを挿入: 1文1行で「名前: テキスト」、名前のない行はナレーション。連続する「> 回答」行は選択肢になり、「# タイトル」で新しいシーンが始まります。Ren'Pyスクリプトも認識(「define」の話者コード、menu、label)。ジャンプはつながりになり、画像と音楽はスキップ。",
