"Früher musste man für einen Kauf zwei Dinge bauen: eine Bedingung „Geld ≥ 500“ und eine Aktion „Geld −500“. Das geht jetzt mit einem Feld: Preis.": "以前は購入に2つ必要でした: 条件「お金 ≥ 500」とアクション「お金 −500」。今は価格の欄1つで済みます。",
