"Färbt Figuren passend zum Hintergrund ein, damit sie nicht wie aufgeklebt wirken.": "背景に合わせてキャラクターに色を付け、浮いて見えないようにします。",
"Füge im Reiter „Beziehungen“ Ray hinzu (Knopf „+ Ray“).": "「関係」タブでRayを追加します(ボタン「+ Ray」)。",
"Füge oben eine Sprache hinzu (z. B. „en“), dann erscheint daneben eine Spalte zum Übersetzen. Im Spiel kann man die Sprache oben umschalten.": "上で言語を追加すると(例:「en」)、横に翻訳用の列が現れます。ゲームでは上部で言語を切り替えられます。",
"Füge rechts unter „Parallax“ eine zweite Ebene hinzu (+ Ebene) und wähle „Parallax Hügel“.": "右の「視差」で2つ目のレイヤーを追加(+ レイヤー)し、「視差 丘」を選びます。",
