"Für": "対象",
"Für Beta-Tester und Modder: Taste ^ öffnet im fertigen Spiel die Entwickler-Konsole (Werte setzen, springen …).": "ベータテスターやMOD制作者向け: 完成したゲームで^キーを押すと開発者コンソールが開きます(値の設定、ジャンプ …)。",
"Für Sprecher:": "声優向け:",
"Für jede Meldung: Position, Animation (auch Zersplittern), Dauer, Text mit Platzhaltern {quest} {reihe} {abschnitt} {figur}, Symbol, Sound oder Jingle. Farben, Rahmen und Hintergrund über „🎨“.": "メッセージごとに: 位置、アニメーション(粉砕を含む)、長さ、プレースホルダー {quest} {reihe} {abschnitt} {figur} つきテキスト、アイコン、効果音またはジングル。色・枠・背景は「🎨」で。",
"Für {name} gibt es noch keine ♥-Punkte im Spiel. {levels} wird erst erreichbar, wenn du irgendwo Punkte vergibst.": "ゲーム内にまだ{name}の♥ポイントがありません。どこかでポイントを与えるまで{levels}には到達できません。",
