"Gegenstand wird verbraucht": "アイテムは消費される",
"Gegenstand „{name}“: Ausrüstungs-Platz fehlt": "アイテム「{name}」: 装備スロットがありません",
"Gegenstände": "アイテム",
"Gegenstände ausrüsten: Kleidung, Werkzeug, Schmuck … Jeder Platz trägt einen Gegenstand. Der Spieler rüstet im Inventar aus (Gegenstand anklicken → „Ausrüsten“). Prüfen mit der Bedingung „👕 Trägt Gegenstand“, z. B. für Missionen, Quests oder wie eine Figur reagiert.": "アイテムを装備: 服、道具、アクセサリー … 各スロットに1つ。プレイヤーはインベントリで装備します(アイテムをクリック →「装備」)。条件「👕 アイテムを装備中」で確認(例: ミッション、クエスト、キャラクターの反応)。",
"Gegenstände im Kampf": "バトル中のアイテム",
"Gegenstände mit Haken „verschenkbar“ können Figuren gegeben werden (Aktion „🎁 Geschenk geben lassen“, z. B. an einem Hub-Objekt). Vorlieben legst du pro Kategorie fest, Sonderfälle pro Gegenstand. Der Spieler entdeckt die Vorlieben erst beim Schenken.": "「贈れる」にチェックしたアイテムはキャラクターに贈れます(アクション「🎁 プレゼントを贈らせる」、例: ハブオブジェクト)。好みはカテゴリごと、特例はアイテムごとに設定。プレイヤーは贈って初めて好みを知ります。",
"Gegenstände mit Platz": "スロットのあるアイテム",
"Gegenstände mit einer Wirkung erscheinen im Kampf unter „Gegenstände“ und werden beim Benutzen verbraucht.": "効果のあるアイテムはバトルの「アイテム」に表示され、消費されます。",
"Gegenstände sammeln, Inventar-Menü mit Taste I.": "アイテムを集める、Iキーでインベントリ。",
"Gegner": "敵",
"Gegner (bis 6)": "敵(最大6)",
"Gegner fehlt": "敵がいません",
"Gegner sollten nach rechts schauen": "敵は右向きにしてください",
"Gegner stehen links und schauen nach rechts. Ohne Bild erscheint das Symbol.": "敵は左に立ち、右を向きます。画像がなければアイコンが表示されます。",
"Geh zurück zur Lern-Szene, klicke die Auswahl an und gib der ersten Antwort ♥ Ray +10.": "学習用シーンに戻り、選択肢をクリックして最初の回答に ♥ Ray +10 を設定します。",
"Geh zurück zur Szene „Lernen · Animations-Editor“, wähle Ray und stelle die neue Idle-Animation ein.": "シーン「学習 · アニメーションエディター」に戻り、Rayを選んで新しい待機アニメーションを設定します。",
