"Haken setzen, was in die Galerie gehört. Bilder schalten sich frei, sobald sie im Spiel einmal zu sehen waren, Musik beim ersten Abspielen, Szenen beim ersten Besuch. Spieler öffnen die Galerie im Hauptmenü (Knopf mit Aktion „Galerie“) oder im Pausenmenü.": "ギャラリーに入れるものにチェック。画像はゲームで一度見ると、音楽は初めて流れたとき、シーンは初訪問時に解放されます。プレイヤーはメインメニュー(アクション「ギャラリー」のボタン)かポーズメニューで開きます。",
