"Hieb": "斬撃",
"Hier animierst du Figuren mit ihren Knochenpunkten: als Idle-Schleife (z. B. ungeduldig wippen), als Geste für einen Schritt (z. B. Winken) oder als ganze Zwischensequenz mit Hintergrund, mehreren Figuren, Kamera und Ton. Zwischensequenzen laufen live im Spiel oder werden als Video gerendert.": "ここではボーンの点でキャラクターを動かします: 待機ループ(例: いらいらと指で叩く)、1ステップのジェスチャー(例: 手を振る)、背景・複数キャラ・カメラ・音つきのカットシーン。カットシーンはゲーム内でライブ再生するか動画として書き出します。",
"Hier bekommt eine Figur ein Skelett. Wähle ein Bild und eine Körper-Vorlage (Zweibeiner, Vierbeiner, Geflügelt …), dann bewegt sie sich weich.": "ここでキャラクターに骨格を付けます。画像と体のテンプレート(二足、四足、翼あり …)を選ぶと、なめらかに動きます。",
"Hier fehlt noch Tiefe …": "ここには奥行きが足りない …",
"Hier gestaltest du alles, was vorgefertigt ist: Sprechblasen, Buttons, Fenster, Schriften, Sounds und Mauszeiger.": "ここで吹き出し、ボタン、ウィンドウ、フォント、効果音、マウスカーソルをまとめてデザインします。",
"Hier gibt es nichts mehr zu tun.": "ここではもうやることはありません。",
"Hier ist nichts mehr.": "ここにはもう何もない。",
"Hier kannst du gerade nicht arbeiten.": "今はここで働けません。",
"Hier legst du Variablen, Gegenstände, Währungen und Loot-Tabellen an. Benutzt werden sie in den Szenen:": "ここで変数、アイテム、通貨、ルートテーブルを作ります。シーンで次のように使います:",
"Hier liegen alle Szenen deines Spiels. Story-Szenen laufen Schritt für Schritt ab, Hub-Szenen (weißer Punkt) sind Orte zum Herumklicken. Neue legst du mit „+ Story“ und „+ Hub“ an.": "ゲームのすべてのシーンがここにあります。ストーリーシーンはステップごとに進み、ハブシーン(白い点)はクリックで探索する場所です。「+ ストーリー」「+ ハブ」で新規作成。",
