"Hintergrund ·": "背景 ·",
"Hintergrund, Musik, Titel oder Logo und das Aussehen der Buttons. Im Reiter „Design“ kannst du den Buttons eigene Bilder geben.": "背景、音楽、タイトルまたはロゴ、ボタンの見た目。「デザイン」タブでボタンに独自画像を設定できます。",
"Hintergrund-Spur": "背景トラック",
