"Hintergründe automatisch an die Tageszeit anpassen (wenn beim Hintergrund keine eigene Tageszeit gewählt ist)": "背景を時間帯に自動で合わせる(背景に独自の時間帯がない場合)",
"Hinweis": "ヒント",
"Hinweis: Das Skelett gehört zum Bild. Ein neues Bild braucht eigene Bones.": "注意: 骨格は画像に属します。新しい画像には独自のボーンが必要です。",
