"Hub-Szene öffnen, Objekt anklicken.": "ハブシーンを開いてオブジェクトをクリックします。",
"Hub-Szenen werden zu Orten, zwischen denen man frei reisen kann – über die Weltkarte (Taste M) und den Knopf „🏠 Zuhause“ (Taste H). Story-Szenen werden zu Ereignissen: Sie starten, wenn man zur passenden Zeit an einen Ort kommt, und kehren danach dorthin zurück. Mit der Aktion „Freie Zeit beginnt / endet“ wechselst du zwischen freiem Herumlaufen und linearer Story.": "ハブシーンは自由に行き来できる場所になります — ワールドマップ(Mキー)と「🏠 自宅」ボタン(Hキー)で移動。ストーリーシーンはイベントになり、正しい時間にその場所へ来ると始まり、終わるとそこに戻ります。アクション「自由時間 開始 / 終了」で自由探索と一本道のストーリーを切り替えます。",
