"Idle-Schleifen und Gesten mit Knochen – oder ganze Zwischensequenzen.": "ボーンによる待機ループとジェスチャー、またはカットシーン全体。",
"Im Inventar erscheint „Benutzen“, sobald hier mindestens eine Aktion steht (z. B. Heiltrank: Leben + 20). Für „Schlüssel auf Tür“ stellst du das am Hub-Objekt ein (Abschnitt „Gegenstand benutzen“).": "ここにアクションが1つでもあれば、インベントリに「使う」が表示されます(例: 回復薬: HP + 20)。「ドアに鍵」の場合はハブオブジェクト側で設定します(「アイテムを使う」欄)。",
"Im Inventar „Benutzen“ anbieten": "インベントリで「使う」を提供",
"Im Inventar: Gegenstand wählen → „Kombinieren …“ → zweiten anklicken. Z. B. Seil + Haken → Enterhaken.": "インベントリで: アイテムを選ぶ →「組み合わせる …」→ 2つ目をクリック。例: ロープ + フック → 鉤縄。",
