"Im Spiel: Inventar → Gegenstand → „Benutzen“ → auf das Objekt klicken. Falscher Gegenstand: „Das funktioniert hier nicht.“": "ゲーム内: インベントリ → アイテム →「使う」→ オブジェクトをクリック。違うアイテム:「ここでは使えない。」",
"Im ganzen Spiel gibt es bisher {pts} ♥-Punkte für {name} (zusammen mit dem Startwert höchstens {max} %). Für {levels} fehlen noch {miss} Punkte.": "現在、ゲーム全体で{name}に♥{pts}ポイントが得られます(初期値込みで最大{max}%)。{levels}にはあと{miss}ポイント足りません。",
