"Irgendwo im Keller liegt der Schlüssel zur Schatzkammer.": "地下室のどこかに宝物庫の鍵がある。",
"Ist es eine Szene, die du nur zum Testen angelegt hast, kannst du die Meldung ausblenden.": "テスト用に作っただけのシーンなら、この通知を非表示にできます。",
