"Je besser gespielt, desto mehr Lohn (40–100 %) und Erfahrung.": "上手にプレイするほど報酬(40–100 %)と経験値が増えます。",
"Jede Hub-Szene kann ein Ort sein. „Per Aktion“ heißt: erst nach der Aktion „📍 Ort freischalten“ (z. B. am Ende von Kapitel 1).": "どのハブシーンも場所になれます。「アクションで」とは、アクション「📍 場所を解放」の後だけ(例: 第1章の終わり)という意味です。",
"Jede Plugin-Aktion erscheint danach überall unter „+ Aktion“. Bild-Parameter lassen sich im Editor austauschen.": "各プラグインアクションは「+ アクション」の下どこにでも表示されます。画像パラメーターはエディターで差し替えられます。",
"Jede Spalte ist ein Klick des Spielers. Clips verschieben, am rechten Rand ziehen zum Verlängern, Doppelklick auf eine Spur legt einen neuen Clip an.": "各列はプレイヤーの1クリックです。クリップを移動、右端をドラッグで延長、トラックをダブルクリックで新しいクリップ。",
"Jede Spalte ist ein Schritt, also ein Klick des Spielers.": "各列は1ステップ、つまりプレイヤーの1クリックです。",
"Jede Zeile ist ein Knochen. Rauten verschieben ändert das Timing, Rechtsklick löscht. Oben im Lineal ziehst du die Abspielposition.": "各行は1本のボーンです。ひし形を動かすとタイミングが変わり、右クリックで削除。上部の目盛りで再生ヘッドをドラッグ。",
"Jeder Status": "任意のステータス",
"Jeder Text hat eine feste ID. Die Timeline verweist nur darauf, deshalb übersetzt du hier alles an einem Ort.": "各テキストには固定IDがあります。タイムラインはそれを参照するだけなので、ここで一か所にまとめて翻訳できます。",
"Jedes Thema ist eine kleine Szene im Lernprojekt. Rechts unten stehen die Aufgaben – das Programm hakt sie selbst ab, sobald du sie erledigt hast. Dein eigenes Projekt bleibt unberührt.": "各テーマは学習プロジェクト内の小さなシーンです。課題は右下にあり、こなすとプログラムが自動でチェックします。あなた自身のプロジェクトは変更されません。",
"Jedes Öffnen würfelt neu. Wer vorher speichert und zurücklädt, kann bessere Beute erzwingen.": "開けるたびに抽選し直します。開ける前にセーブしてロードすれば、良い戦利品を狙えてしまいます。",
