"Jobs startest du mit der Aktion „Jobs: Arbeiten gehen“, z. B. an einem Hub-Objekt (Tür zur Taverne) oder in einer Antwort. Alles hier sind Platzhalter – Texte, Bild und Werte gehören dir.": "仕事はアクション「仕事: 働きに行く」で開始します(例: ハブオブジェクト(酒場のドア)や回答)。ここにあるものはすべて仮のもので、テキスト・画像・数値はあなたが決めます。",
