"Kampf wie in klassischen Rollenspielen: rundenbasiert, Seitenansicht, Gruppe aus bis zu vier Helden. Gestartet wird ein Kampf mit der Aktion „⚔ Kampf starten“ – an einem Dialog, einer Antwort oder einem Hub-Objekt. Sieg, Niederlage und Flucht führen in eigene Szenen; „⚔ Kampf gewonnen“ fragt das Ergebnis später ab.": "クラシックRPGのような戦闘: ターン制、サイドビュー、最大4人のヒーローのパーティー。戦闘はアクション「⚔ 戦闘開始」で始まります — セリフ、回答、ハブオブジェクトに設定。勝利・敗北・逃走はそれぞれのシーンへ進み、「⚔ 戦闘に勝利」で後から結果を確認できます。",
