"Kaputte Bedingungen verweisen auf etwas, das es nicht mehr gibt – im Spiel gelten sie als NICHT erfüllt. Dazu Hinweise zu Welt, Orten und Quests.": "壊れた条件は存在しなくなったものを参照しています — ゲーム内では「未達成」として扱われます。ワールド、場所、クエストに関する注意も表示します。",
