"Klick-Reflex": "クリック反射",
"Klick-Reflex, Memory, Puzzle, Kochen & Brauen, Münzwurf, Blütenblätter zupfen. Jedes liefert ein Ergebnis für Lohn, Beziehung oder Pfad.": "クリック反射、神経衰弱、パズル、料理と調合、コイントス、花占い。どれも報酬、関係、分岐のための結果を返します。",
"Klick-Regeln": "クリックのルール",
"Klick: auf-/zuklappen · Rechtsklick: umbenennen, löschen · Szenen hierher ziehen": "クリック: 開く/閉じる · 右クリック: 名前変更、削除 · ここにシーンをドラッグ",
"Klicke Punkt für Punkt entlang einer Strähne, eines Flügels oder Schweifs. Beginnst du auf einem Gelenk, hängt die Kette daran. Rechts „Kette fertig“ oder Doppelklick.": "髪の束、翼、尻尾に沿って1点ずつクリック。関節から始めるとチェーンがそこにつながります。右の「チェーンを完了」かダブルクリックで終了。",
"Klicke Ray in der Timeline (Figur 1) an.": "タイムラインでRay(キャラクター1)をクリックします。",
"Klicke Zutaten an, um sie hineinzugeben. Klick im Topf nimmt sie wieder heraus.": "材料をクリックで追加。鍋の中をクリックすると取り出します。",
"Klicke auf den Skill, der vorher gekauft sein muss.": "先に購入が必要なスキルをクリックします。",
