"Klicke die Blütenblätter ab": "花びら占い",
"Klicke die erste Dialogzeile an.": "最初のセリフをクリックします。",
"Klicke einen Knochen an, um Bewegung und Jiggle-Physik einzustellen. Weiße Punkte auf Knochen zeigen, dass Physik aktiv ist.": "ボーンをクリックして動きと揺れ物理を設定。ボーン上の白い点は物理が有効な印です。",
"Klicke einen Skill an, um Name, Kosten, Voraussetzungen und Wirkung einzustellen.": "スキルをクリックして名前、コスト、前提条件、効果を設定します。",
"Klicke links auf eine Zeile, um Bedingungen, Belohnungen und Tipps einzustellen.": "左の行をクリックして条件、報酬、ヒントを設定します。",
"Klicke links unten auf die Spielgröße („Spiel ca. … MB“).": "左下のゲームサイズ(「ゲーム 約 … MB」)をクリックします。",
"Klicke oben über der Bühne auf die Leistungs-Ampel („Leistung: …“).": "ステージ上のパフォーマンス表示(「パフォーマンス: …」)をクリックします。",
