"Lege links eine Animation an.": "左でアニメーションを作成してください。",
"Lege links eine Loot-Tabelle an. Benutzt wird sie über die Aktion „Loot-Tabelle würfeln“, z. B. an einer Truhe im Hub.": "左でルートテーブルを作成してください。アクション「ルートテーブルを抽選」で使います(例: ハブの宝箱)。",
"Lege links eine Story- oder Hub-Szene an.": "左でストーリーシーンかハブシーンを作成してください。",
