"Lege rechts unter „Bewegung (Keyframes)“ einen Keyframe bei Schritt 3 an (vorher oben Schritt 3 wählen).": "右の「動き(キーフレーム)」でステップ3にキーフレームを作成します(先に上でステップ3を選択)。",
"Lege weitere Sprachen an und übersetze Zeile für Zeile. Export als CSV für Übersetzer und als Sprecher-Skript für Sprachaufnahmen.": "言語を追加して1行ずつ翻訳。翻訳者向けにCSV、ボイス収録用に台本として書き出せます。",
"Lege zuerst Gegenstände oder Währungen an.": "まずアイテムか通貨を作成してください。",
