"Mit der VN Timeline Engine baust du Visual Novels wie in einem Schnittprogramm: Bilder, Texte und Töne liegen als Clips auf einer Timeline. Das Tutorial-Projekt hat sieben kleine Szenen, jede zeigt genau ein Thema. Diese Tour dauert etwa zwei Minuten.": "VN Timeline Engineでは動画編集ソフトのようにビジュアルノベルを作れます: 画像、テキスト、音がタイムライン上のクリップとして並びます。チュートリアルプロジェクトには7つの小さなシーンがあり、それぞれが1つのテーマを扱います。このツアーは約2分です。",
"Mit „Zur Stelle“ hinspringen und in der Bedingung das Fehlende neu auswählen.": "「そこへ移動」を使い、条件で欠けているものを選び直してください。",
