"Noch keine Quests. Lege oben eine Quest oder eine Questreihe an.": "まだクエストがありません。上でクエストかクエストシリーズを作成してください。",
"Noch keine Rezepte. Ohne Rezept ergibt Kochen immer „Matsch“.": "まだレシピがありません。レシピがないと料理は常に「ドロドロ」になります。",
"Noch keine Schriften (TTF, OTF, WOFF). Importieren oder hierher ziehen.": "まだフォントがありません(TTF, OTF, WOFF)。インポートするかここへドラッグしてください。",
"Noch keine Skills. „+ Skill“ legt einen an, oder starte mit einer Vorlage.": "まだスキルがありません。「+ スキル」で作成するか、テンプレートから始めましょう。",
"Noch keine Sprecher. Sobald ein Dialog einen Sprecher hat, kannst du ihm hier eine eigene Sprechblase geben.": "まだ話者がいません。セリフに話者が付くと、ここで専用の吹き出しを設定できます。",
"Noch keine Videos (WebM, MP4).": "まだ動画がありません(WebM, MP4)。",
"Noch keine Währung. Lege unter „Währungen“ zum Beispiel „Gold“ an.": "まだ通貨がありません。「通貨」で作成してください(例:「ゴールド」)。",
"Noch keine eigenen Schriften. TTF, OTF, WOFF oder WOFF2 importieren oder in die Dateiliste ziehen.": "まだ独自フォントがありません。TTF、OTF、WOFF、WOFF2をインポートするか、ファイル一覧へドラッグしてください。",
"Noch keiner. Unter „Gegenstände“ in der Spalte „Ausrüsten“ einen Platz wählen.": "まだありません。「アイテム」の「装備」列でスロットを選んでください。",
"Noch leer. Am schnellsten geht es mit dem Beispiel: drei Helden, drei Gegner, sechs Fähigkeiten und zwei Kämpfe – alles änderbar.": "まだ空です。サンプルから始めるのが最速: ヒーロー3人、敵3体、アビリティ7つ、戦闘2つ — すべて編集可能。",
"Noch leer. Am schnellsten geht es mit dem Beispiel: drei Helden, drei Gegner, sieben Fähigkeiten und zwei Kämpfe – alles änderbar.": "まだ空です。サンプルから始めるのが最速: ヒーロー3人、敵3体、アビリティ7つ、戦闘2つ — すべて編集可能。",
"Noch leer. Das Beispiel „Königreich“ legt Holz und Stein als Rohstoffe an, fünf Gebäude (Holzfällerhütte bis Burg) und drei Ziele – alles änderbar.": "まだ空です。サンプル「王国」は資源として木と石、建物5つ(木こり小屋から城まで)、目標3つを作成します — すべて編集可能。",
