"Sechs Minispiele. Du startest sie über „+ Aktion“ → „Minispiele: …“ – in einer Antwort, an einem Hub-Objekt, in einem Dialog oder als Minispiel eines Jobs. Einstellungen und Bilder wählst du direkt an der Aktion. Jedes Spiel liefert ein Ergebnis von 0–100 % (Feld „Ergebnis in“ → Variable).": "6つのミニゲーム。「+ アクション」→「ミニゲーム: …」で開始 — 回答、ハブオブジェクト、セリフ、または仕事のミニゲームとして。設定と画像はアクション上で直接選びます。どのゲームも0–100 %の結果を返します(欄「結果の保存先」→ 変数)。",
"Sieben Minispiele. Du startest sie über „+ Aktion“ → „Minispiele: …“ – in einer Antwort, an einem Hub-Objekt, in einem Dialog oder als Minispiel eines Jobs. Einstellungen und Bilder wählst du direkt an der Aktion. Jedes Spiel liefert ein Ergebnis von 0–100 % (Feld „Ergebnis in“ → Variable).": "7つのミニゲーム。「+ アクション」→「ミニゲーム: …」で開始 — 回答、ハブオブジェクト、セリフ、または仕事のミニゲームとして。設定と画像はアクション上で直接選びます。どのゲームも0–100 %の結果を返します(欄「結果の保存先」→ 変数)。",
