"Tipp: Auf gebaute Gebäude klicken bringt sofort etwas.": "ヒント: 建設済みの建物をクリックするとすぐに何か得られます。",
"Tipp: Beim Testen öffnet die Taste ^ (oder F12) die Entwickler-Konsole mit echten Bildern pro Sekunde.": "ヒント: テスト中は ^ キー(またはF12)で実際のフレームレートつき開発者コンソールが開きます。",
"Tipp: Das Rechteck darf etwas größer als der geschlossene Mund sein. Es öffnet sich von oben nach unten.": "ヒント: 長方形は閉じた口より少し大きくて構いません。上から下へ開きます。",
"Tipp: Eine Antwort „Schlafen gehen“ mit der Aktion „Zeit vergehen lassen → nächster Tag“ und Hub-Objekte mit der Bedingung „Tageszeit ist Abend“ – fertig ist ein Tagesablauf.": "ヒント: アクション「時間を進める → 翌日」つきの回答「寝る」と、条件「時間帯が夕方」のハブオブジェクトがあれば、日課のできあがり。",
"Tipp: Figuren lassen sich auf der Bühne auch direkt ziehen – waagerecht für die Position, senkrecht für die Höhe (Umschalt: nur eine Richtung).": "ヒント: キャラクターはステージ上で直接ドラッグもできます — 横で位置、縦で高さ(Shift: 一方向のみ)。",
"Tipp: Mit dem Setup (VN-Timeline-Engine-Setup.exe) kommen Updates automatisch und laden nur die Änderungen. Deine Projekte bleiben dabei, wo sie sind.": "ヒント: セットアップ版(VN-Timeline-Engine-Setup.exe)なら更新が自動で届き、変更部分だけダウンロードします。プロジェクトはそのまま残ります。",
"Tipp: Mit „100× simulieren“ siehst du, wie schwer der Kampf ist.": "ヒント:「100回シミュレート」で戦闘の難しさがわかります。",
"Tipp: Schreibt der Held seine Stufe in eine Variable, kann ein Skilltree bei jedem Stufenaufstieg Punkte geben.": "ヒント: ヒーローがレベルを変数に書き込めば、スキルツリーでレベルアップごとにポイントを与えられます。",
"Tipp: So kannst du z. B. Vorschau-Töne über Kopfhörer hören und das Test-Spiel über die Boxen. Spieler stellen ihr Gerät im fertigen Spiel unter Einstellungen → Tonausgabe selbst ein.": "ヒント: これでプレビュー音をヘッドホンで、テストゲームをスピーカーで聴けます。プレイヤーは完成版の 設定 → 音声出力 でデバイスを選べます。",
