"“ wird noch verwendet. Trotzdem aus dem Projekt entfernen? Die Clips bleiben als leere Clips erhalten.": "」はまだ使用中です。それでもプロジェクトから削除しますか? クリップは空のクリップとして残ります。",
"“. Läuft dann als Dauer-Schleife.": "」。その後は連続ループで再生されます。",
"“. Spielt einmal und kehrt weich ins Idle zurück.": "」。1回再生して、なめらかに待機に戻ります。",
"“: Pin zeigt auf keinen Ort": "」: ピンがどの場所も指していません",
"“: Unterkarte fehlt": "」: サブマップがありません",
"„+ Neues Plugin“ legt eine Vorlage an, „Code bearbeiten“ öffnet den eingebauten Editor. Die Anleitung steht in PLUGINS.md.": "「+ 新しいプラグイン」でテンプレートを作成、「コードを編集」で内蔵エディターを開きます。説明書は PLUGINS.md にあります。",
"„Auf Preis umstellen“ drücken – Bedingung und Geld-Aktion werden durch den Preis ersetzt.": "「価格に変換」を押すと、条件とお金のアクションが価格に置き換わります。",
"„Fortsetzen“ lädt den neuesten Spielstand und ist ausgegraut, solange es keinen gibt. „Beenden“ schließt das fertige Spiel, beim Testen geht es zurück zum Editor.": "「続きから」は最新のセーブをロードし、セーブがない間はグレー表示です。「終了」は完成版ゲームを閉じ、テスト時はエディターに戻ります。",
"„Liebt mich, liebt mich nicht“ – die Blattzahl sorgt für ein echtes 50:50.": "「好き、嫌い」— 花びらの数で本当の50:50になります。",
"„Menü testen“ zeigt das Menü so, wie es der Spieler sieht.": "「メニューをテスト」でプレイヤーが見るとおりにメニューを表示します。",
"„Neu“ zeigen als": "「新規」の表示方法",
"„Szene testen“ spielt die offene Szene ab dem gewählten Schritt. „Spiel testen“ startet alles mit Hauptmenü, genau wie später beim Spieler.": "「シーンをテスト」は開いているシーンを選んだステップから再生します。「ゲームをテスト」は後のプレイヤーと同じくメインメニューからすべて開始します。",
"„{name}“ ist ein Ausrüstungs-Gegenstand. Zum Anziehen besser „👕 Trägt Gegenstand“ nehmen – „benutzt“ heißt: im Inventar auf „Benutzen“ geklickt.": "「{name}」は装備アイテムです。装備にはむしろ「👕 アイテムを装備中」を使ってください — 「使用した」はインベントリで「使う」を押したという意味です。",
"„{name}“ verbinden mit …": "「{name}」を接続 …",
"„{name}“ wird gekauft": "「{name}」は購入可能",
"„{obj}“ in „{scene}“ prüft Geld und zieht es dann ab. Dafür gibt es jetzt den Preis direkt am Objekt – mit Rückfrage und Meldung bei zu wenig Geld.": "「{scene}」の「{obj}」はお金を確認してから差し引いています。現在はそのためにオブジェクトに直接価格を設定できます — 確認つきで、お金が足りないときはメッセージも表示します。",
"• Antworten einer Auswahl: Bedingungen („nur wenn“) und Aktionen („bei Auswahl“)": "• 選択肢の回答: 条件(「条件」)とアクション(「選んだとき」)",
"• Dialog-Clips: Aktionen beim Erreichen": "• セリフクリップ: 到達時のアクション",
