"Anleitung für KI": "AI向けガイド",
"Aufbau startet": "建設開始",
"Aufbau: Start „durch die Aktion“, aber die Aktion „🏰 Aufbau starten“ kommt nirgends vor – er würde nie starten.": "建設: 開始が「アクションで」ですが、アクション「🏰 建設開始」がどこにも使われていません — 開始されません。",
"Aufbau: Start „sobald Bedingungen stimmen“, aber es ist keine Bedingung eingetragen – er würde nie starten.": "建設: 開始が「条件を満たしたら」ですが、条件が設定されていません — 開始されません。",
"Auftritt (Art und Dauer)": "登場(種類と長さ)",
"Beim Klick läuft ein Dialog über dem Hub, danach geht es zurück": "クリックでハブの上に会話が流れ、その後戻る",
"Bild aus der Dateiliste wählen – oder einfach von links hierher ziehen": "ファイル一覧から画像を選ぶか、左からここへドラッグ",
"Bild einfügen": "画像を挿入",
"Bild-Geschenke": "画像つきプレゼント",
"Blau-Gelb-Schwäche (Tritanopie)": "青黄色覚異常(第3色覚)",
"Damit ChatGPT, Gemini, Grok, Claude & Co. dein Projekt verstehen und bearbeiten können – ganz ohne Quellcode der Engine. Die Anleitung beschreibt das Dateiformat, alle Bedingungen und Aktionen, die Oberfläche und eine Übersicht deines Projekts. Gib der KI den Projektordner (mit dieser Datei) oder füge den Text in den Chat ein.": "ChatGPT、Gemini、Grok、Claudeなどがエンジンのソースコードなしでプロジェクトを理解・編集できるように。ガイドにはファイル形式、すべての条件とアクション、インターフェース、プロジェクトの概要が書かれています。AIにプロジェクトフォルダー(このファイルつき)を渡すか、テキストをチャットに貼り付けてください。",
"Der Aufbau startet erst durch ein Ereignis in der Geschichte.": "建設はストーリー上のイベントでのみ始まります。",
"Der Aufbau startet, sobald es in der Geschichte so weit ist.": "ストーリーがそこに達すると建設が始まります。",
"Die Produktion beginnt in dem Moment, in dem der Spieler den Aufbau zum ersten Mal öffnet – vorher wird nichts gesammelt.": "生産はプレイヤーが初めて建設画面を開いた瞬間に始まります — それ以前は何も貯まりません。",
"Diese Szene kehrt am Ende nicht zum Hub zurück.": "このシーンは終了時にハブへ戻りません。",
"Effekte, Mischmodus und Deckkraft": "エフェクト、合成モード、不透明度",
"Ein Dialog mit allen Möglichkeiten der Timeline, der über dem Hub abläuft und danach zurückkehrt": "タイムラインの機能をすべて使える会話。ハブの上で再生され、その後戻ります",
"Eine freie Fläche zum Planen – für dich allein oder fürs Team. Bilder aus der Dateiliste hierher ziehen, Notizen per Doppelklick, Überschriften für Kapitel, Pfeile für die Reihenfolge. Karten lassen sich mit Szenen verknüpfen, dann öffnet ein Klick die Szene.": "企画のための自由なスペース — 自分用にもチーム用にも。ファイル一覧から画像をドラッグ、ダブルクリックでメモ、章には見出し、順番には矢印。カードはシーンにリンクでき、クリックでシーンを開きます。",
"Einfügen bei": "貼り付け先",
"Farbhilfe (Farbenblind)": "色覚サポート",
"Figuren (Filter in der Galerie) – auch mehrere, z. B. bei Gruppenbildern": "キャラクター(ギャラリーのフィルター)— 複数可、例: 集合絵",
"Format bei {n} Figur(en) eingefügt": "{n}人のキャラクターに書式を貼り付けました",
"Format einfügen …": "書式を貼り付け …",
"Format kopieren": "書式をコピー",
"Format von „{name}“ einfügen": "「{name}」の書式を貼り付け",
"Format von „{name}“ kopiert": "「{name}」の書式をコピーしました",
"Frei transformieren: Figur auf der Bühne ziehen (rastet an Mitte, Dritteln, Boden und anderen Figuren ein – Alt = frei), an den Ecken skalieren, am Kreis oben drehen (Umschalt: 15°-Schritte). Werte lassen sich auch eintippen.": "自由変形: ステージ上でキャラクターをドラッグ(中央、三分割線、床、他のキャラクターに吸着 — Alt = 自由)、角で拡大縮小、上の円で回転(Shift: 15°刻み)。値の直接入力も可能。",
"Färbt Bühne und Testspiel so ein, wie es Menschen mit dieser Farbschwäche ungefähr sehen. Gut zum Prüfen, ob wichtige Dinge (Hinweise, Rätsel, Knöpfe) nicht nur an der Farbe hängen.": "ステージとテストゲームを、この色覚特性を持つ人の見え方に近づけて表示します。重要なもの(ヒント、パズル、ボタン)が色だけに頼っていないか確認できます。",
"Für die Planung: Szenen skizzieren, Ideen sammeln, Reihenfolge festlegen. Das Storyboard wird im Projekt gespeichert – wer den Projektordner teilt, sieht dieselbe Übersicht. Im fertigen Spiel ist es nicht enthalten.": "企画用: シーンのラフ、アイデア集め、順番決め。ストーリーボードはプロジェクトに保存され、プロジェクトフォルダーを共有する人は同じ概要を見られます。完成版ゲームには含まれません。",
"Gilt nur für diesen Editor auf diesem Computer. Für Spieler gibt es eigene Einstellungen im Spiel (Menü → Lesen & Barrierefreiheit).": "このPCのこのエディターだけに適用されます。プレイヤーはゲーム内に独自の設定があります(メニュー → 読みやすさとアクセシビリティ)。",
"Grün-Schwäche (Deuteranopie)": "緑色覚異常(第2色覚)",
"In die Zwischenablage kopiert": "クリップボードにコピーしました",
"Jetzt die Zielkarte anklicken (Esc = abbrechen)": "ターゲットのカードをクリック(Esc = キャンセル)",
"Keyframes (Bewegungen über mehrere Schritte)": "キーフレーム(複数ステップにわたる動き)",
"Konnte nicht in den Projektordner schreiben – bitte „Speichern unter …“ benutzen.": "プロジェクトフォルダーに書き込めませんでした —「名前を付けて保存 …」を使ってください。",
"Kopieren ging nicht – bitte „Speichern unter …“ benutzen.": "コピーに失敗しました —「名前を付けて保存 …」を使ってください。",
"Kurze Zeilen (hier eintippen)": "短い行(ここに入力)",
"Leeres Storyboard": "空のストーリーボード",
"Läuft über dem Hub (Hintergrund und Objekte bleiben sichtbar, wenn die Szene keinen eigenen Hintergrund hat). Figuren, Handy-Chat, Auswahl, Aktionen – alles wie in jeder Story-Szene. Am Ende geht es zurück in den Hub.": "ハブの上で再生されます(シーンに独自の背景がなければ背景とオブジェクトは見えたまま)。キャラクター、スマホチャット、選択肢、アクション — どのストーリーシーンとも同じです。最後にハブへ戻ります。",
"Mit Szene verknüpfen": "シーンにリンク",
"Mit Szene verknüpfen …": "シーンにリンク …",
"Notiz …": "メモ …",
