"Pfeil zu …": "矢印 …",
"Position (waagerecht und Höhe)": "位置(横と高さ)",
"Position, Größe, Effekte …": "位置、サイズ、エフェクト …",
"Pro Stunde lohnt sich meist mit „auch bei geschlossenem Spiel“ – sonst müsste der Spieler eine Stunde mit offenem Spiel warten.": "1時間ごとは「ゲームを閉じている間も」と組み合わせるのが最適です — そうでないとプレイヤーはゲームを開いたまま1時間待つことになります。",
"Rot-Schwäche (Protanopie)": "赤色覚異常(第1色覚)",
"Ruhige Oberfläche: keine Animationen und kein Blinken, gedämpfte Farben, deutlichere Rahmen um das, was gerade ausgewählt ist. Hilft bei Reizüberflutung und Konzentration.": "落ち着いたインターフェース: アニメーションや点滅なし、控えめな色、選択中のものに明確な輪郭。感覚過敏や集中に役立ちます。",
"Sekunde": "秒",
"Setze die Aktion „🏰 Aufbau starten“ z. B. an eine Dialogzeile („Ab heute gehört dir das Dorf!“), an eine Antwort oder an ein Objekt im Hub.": "アクション「🏰 建設開始」を、例えばセリフ(「今日からこの村はあなたのもの!」)、回答、ハブオブジェクトに設定します。",
"Spuren, Warnungen und Markierungen in Farben, die sich auch bei Rot-Grün- oder Blau-Gelb-Schwäche gut unterscheiden lassen.": "赤緑や青黄の色覚特性があっても区別しやすい色のトラック、警告、強調表示。",
"Stunde": "時間",
"Teamarbeit: Das Storyboard steht in der project.json. Liegt der Projektordner in einem geteilten Ordner (z. B. OneDrive, Dropbox, Google Drive), sehen alle dieselben Karten. Bitte nicht gleichzeitig im selben Projekt arbeiten – wer zuletzt speichert, gewinnt.": "チーム作業: ストーリーボードは project.json に保存されます。プロジェクトフォルダーが共有フォルダー(例: OneDrive、Dropbox、Google Drive)にあれば、全員が同じカードを見られます。同じプロジェクトで同時に作業しないでください — 最後に保存した人の内容が残ります。",
"Text bearbeiten": "テキストを編集",
"Timeline-Dialog (Figuren, Handy, Auswahl …)": "タイムライン会話(キャラクター、スマホ、選択肢 …)",
