"Von": "作成者",
"Vorschau: Spiel mit den Augen farbenblinder Spieler sehen": "プレビュー: 色覚特性のあるプレイヤーの目でゲームを見る",
"Weniger Effekte": "エフェクトを減らす",
"Wähle, was übertragen wird. Alles, was nicht angehakt ist, bleibt wie es ist.": "転送する項目を選びます。チェックしていないものはそのまま残ります。",
"Ziehe Bilder aus der Dateiliste links hierher, Doppelklick legt eine Notiz an.": "左のファイル一覧から画像をここへドラッグ。ダブルクリックでメモを作成。",
"Ziehen = Größe ändern": "ドラッグ = サイズ変更",
"Ziehen = drehen (Umschalt: 15°-Schritte) · Doppelklick = gerade": "ドラッグ = 回転(Shift: 15°刻み)· ダブルクリック = まっすぐ",
"Ziehen = verschieben · Ecke = Größe · Doppelklick = Text bearbeiten · Rechtsklick = Farbe, Pfeil, Szene · leere Fläche ziehen = Ansicht verschieben · Strg + Mausrad = Zoom · Entf = löschen": "ドラッグ = 移動 · 角 = サイズ · ダブルクリック = テキスト編集 · 右クリック = 色、矢印、シーン · 空き部分をドラッグ = スクロール · Ctrl + ホイール = ズーム · Del = 削除",
"Zum Beispiel „✔ Spieler hat … eine Szene gesehen“ oder eine Variable, die ein Dialog setzt. Danach läuft der Aufbau dauerhaft.": "例えば「✔ プレイヤーが … シーンを見た」や、会話で設定される変数。その後、建設は動き続けます。",
