" (Gliederpuppe)": " (関節人形)",
"+ Gliederpuppe": "+ 関節人形",
"+ Neue Gliederpuppe": "+ 新しい関節人形",
"1. Körperteile als einzelne PNGs vorbereiten (transparent). 2. Puppe anlegen und die Bilder auf die Fläche ziehen. 3. Bei jedem Teil den roten Pin auf das Gelenk ziehen und auf dem Eltern-Teil loslassen (Unterarm-Pin auf den Oberarm, Oberarm-Pin auf den Torso). 4. Im Animations-Editor einen Darsteller anlegen und „Gliederpuppe“ wählen.": "1. 体のパーツを個別のPNG(透過)で用意します。2. 人形を作成し、画像をボードにドラッグします。3. 各パーツの赤いピンを関節にドラッグし、親パーツの上で離します(前腕のピンは上腕へ、上腕のピンは胴体へ)。4. アニメーションエディターでアクターを追加し「関節人形」を選びます。",
"Animation (Bones)": "アニメーション(ボーン)",
"Animation (Gliederpuppe)": "アニメーション(関節人形)",
"Ausprobieren: Teil ziehen = um den Pin drehen · Umschalt + ziehen = IK (die Kette folgt der Maus) · Wurzel-Teil ziehen = ganze Figur verschieben. Nichts davon wird gespeichert.": "試す: パーツをドラッグ = ピンを中心に回転 · Shift + ドラッグ = IK(チェーンがマウスに追従)· ルートパーツをドラッグ = 全体を移動。どれも保存されません。",
"Bild als neues Teil hinzufügen": "画像を新しいパーツとして追加",
"Bilder aus der Dateiliste hierher ziehen = neues Teil · Teil ziehen = verschieben (Kinder wandern mit, Alt = nur dieses Teil) · roten Pin ziehen = Gelenk setzen; auf einem anderen Teil loslassen = daran anhängen · Entf = Teil löschen": "ファイル一覧から画像をここへドラッグ = 新しいパーツ · パーツをドラッグ = 移動(子も追従、Alt = このパーツのみ)· 赤いピンをドラッグ = 関節を設定、別のパーツの上で離す = そこに接続 · Del = パーツを削除",
"Bilder aus der Dateiliste hierher ziehen – jedes Bild wird ein Körperteil.": "ファイル一覧から画像をここへドラッグ — 各画像が体のパーツになります。",
"Bones": "ボーン",
"Bones benutzen (Verformen, Atmen, Physik aus dem Bones-Editor)": "ボーンを使う(変形、呼吸、ボーンエディターの物理)",
"Bones dieses Teils": "このパーツのボーン",
"Die Engine verfolgt alle Wege ab der Startszene. Orte der Weltkarte zählen als erreichbar (man reist hin), ebenso alles, was von dort aus weitergeht. Kommt sie trotzdem nirgends bei dieser Szene an, erscheint die Meldung.": "エンジンは開始シーンからすべての経路をたどります。ワールドマップ上の場所(移動できる)とそこから続くものは到達可能とみなします。それでもこのシーンに一度も到達しない場合、この通知が出ます。",
"Diese Figur hat noch keine Bones. ": "このキャラクターにはまだボーンがありません。 ",
"Dieses Teil hat noch keine Bones. Mit Bones lässt es sich zusätzlich verformen – z. B. Haare, Schwanz, Umhang mit Physik.": "このパーツにはまだボーンがありません。ボーンがあれば変形もできます — 例: 物理つきの髪、尻尾、マント。",
"Drehung in Ruhe °": "基本回転 °",
"Ebenen-Figuren (Körper, Gesicht, Outfit) und Gliederpuppen (Körperteile mit Gelenken) legst du oben unter „Figuren“ an.": "レイヤーキャラクター(体、顔、服)と関節人形(関節のある体のパーツ)は上の「キャラクター」で作成します。",
"Figuren brauchen dafür Bones (Reiter „Figuren“ → „Bones & Blinzeln“) – oder du nimmst eine Gliederpuppe aus Körperteilen (Reiter „Figuren“ → „Gliederpuppen“).": "このためにはキャラクターにボーンが必要です(タブ「キャラクター」→「ボーンとまばたき」)— または体のパーツで作った関節人形を使います(タブ「キャラクター」→「関節人形」)。",
"Gliederpuppe": "関節人形",
"Gliederpuppe löschen": "関節人形を削除",
"Gliederpuppen": "関節人形",
"Hängt an (Eltern-Teil)": "接続先(親パーツ)",
"Idle": "待機",
"Idle abspielen": "待機を再生",
"Idle dieses Teils": "このパーツの待機",
"Idle · ": "待機 · ",
"Idle-Bewegung und Gesten kommen aus dem Animations-Editor (Darsteller = diese Gliederpuppe).": "待機モーションとジェスチャーはアニメーションエディターで作ります(アクター = この関節人形)。",
"Jiggle schwingt nach, wenn sich das Eltern-Teil bewegt (Haare, Ohren, Schwanz). Unterschiedlicher Versatz bei mehreren Teilen wirkt lebendiger.": "揺れは親パーツが動いた後に揺れ戻します(髪、耳、尻尾)。複数のパーツでずれを変えると生き生きして見えます。",
"Keine Antwort, kein „Danach weiter zu“, kein Hub-Objekt, kein Hub-Dialog, keine Reise und keine Aktion führt zu dieser Szene. Spieler sehen sie nie.": "このシーンへ至る回答、「次に進む」、ハブオブジェクト、ハブ会話、移動、アクションがありません。プレイヤーには決して表示されません。",
"Lösen": "解除",
"Name": "名前",
"Neue Gliederpuppe": "新しい関節人形",
"Pin X (im Bild)": "ピン X(画像内)",
"Pin Y (im Bild)": "ピン Y(画像内)",
"Pins": "ピン",
"Puppe": "人形",
"Puppenspiel: Teil oder Endpunkt ziehen = um den Pin drehen · Umschalt + ziehen = IK (Kette folgt der Maus) · Pfeile (rot X, grün Y, gelb frei) = ganze Figur verschieben · Doppelklick auf ein Teil = festpinnen (bleibt an Ort und Stelle, wenn sich der Körper bewegt).": "人形操作: パーツか先端をドラッグ = ピンを中心に回転 · Shift + ドラッグ = IK(チェーンがマウスに追従)· 矢印(赤 X、緑 Y、黄 自由)= 全体を移動 · パーツをダブルクリック = 固定(体が動いてもその場に残る)。",
"Setze eine Figur aus einzelnen Körperteilen zusammen – Kopf, Torso, Oberarm, Unterarm, Hand … – jedes Teil ein eigenes Bild mit transparentem Hintergrund. Verbinde die Teile mit Gelenk-Pins: Der Oberarm hängt an der Schulter, der Unterarm am Ellbogen. Dann lässt sich die Figur wie eine Puppe bewegen, im Animations-Editor animieren und im Spiel mit Idle-Bewegungen zeigen.": "体のパーツを分けてキャラクターを作ります — 頭、胴体、上腕、前腕、手 … それぞれ透過背景の独立した画像です。パーツは関節ピンでつなぎます: 上腕は肩に、前腕はひじに。するとキャラクターは人形のように動き、アニメーションエディターでアニメーションでき、ゲームでは待機モーションを見せます。",
"Spiegelt das Teil und seine Kinder an der Mitte der Puppe – z. B. linken Arm als rechten Arm anlegen": "パーツとその子を人形の中心で反転 — 例: 左腕から右腕を作る",
"Stärke °": "強さ °",
"Szene „{name}“ wird nirgends betreten – kein Weg vom Start, keine Reise, kein Objekt, keine Aktion führt dorthin.": "シーン「{name}」には一度も入りません — 開始からの経路、移動、オブジェクト、アクションのどれも通じていません。",
"Teil": "パーツ",
"Teil auf der Fläche anklicken. Der rote Punkt ist sein Gelenk-Pin: auf das Gelenk ziehen und über dem Teil loslassen, an dem es hängen soll.": "ボード上のパーツをクリックします。赤い点が関節ピンです: 関節までドラッグし、つなげたいパーツの上で離します。",
