"Timeline: Figuren-Clip → „Art der Figur“ → diese Gliederpuppe. Animieren: Reiter „Animation“ → Darsteller → „🦴 Gliederpuppe“.": "タイムライン: キャラクタークリップ →「キャラクターの種類」→ この関節人形。アニメーション: タブ「アニメーション」→ アクター →「🦴 関節人形」。",
