"Radierer: Teil wählen und über die Kante malen · Größe und Kantenweichheit rechts · „Wiederherstellen“ malt das Original zurück · Mausrad + Strg = Pinselgröße · Speichern legt eine neue Bilddatei an, das Original bleibt erhalten.": "消しゴム: パーツを選んで縁を塗ります · サイズと縁のやわらかさは右 ·「復元」で元の画像を塗り戻す · Ctrl + マウスホイール = ブラシサイズ · 保存すると新しい画像ファイルが作られ、元は保持されます。",
"Ungespeicherte Radierer-Änderungen verwerfen?": "保存していない消しゴムの変更を破棄しますか?",
