"Weiche Kante = sanfter Übergang (gut für Gelenke, an denen zwei Teile überlappen). Wiederherstellen malt das Original zurück. Gespeichert wird als neue Bilddatei – das Original bleibt erhalten.": "やわらかい縁 = なめらかな境目(2つのパーツが重なる関節に最適)。復元で元を塗り戻します。新しい画像ファイルとして保存され、元は保持されます。",
