"Laufen als Schleife leise unter der Musik, solange Tageszeit, Jahreszeit und Ort passen – und blenden beim Wechsel weich über.": "時間帯、季節、場所が合っている間は音楽の下で静かにループし、変わるとクロスフェードします。",
