"Ein Handy oder ein Computer im Spiel: Startbildschirm mit Apps wie Nachrichten, Inventar, Beziehungen, Galerie, Quests oder eigenen Apps (Seiten, Aktionen, Sprung in eine Szene). Öffnen per Knopf, Taste oder mit der Aktion „📱 Gerät öffnen“ – z. B. auf einer Hitbox im Hub (der Laptop auf dem Schreibtisch).": "ゲーム内のスマホやパソコン: メッセージ、インベントリ、関係、ギャラリー、クエスト、独自アプリ(ページ、アクション、シーンへジャンプ)が並ぶホーム画面。ボタン、キー、アクション「📱 デバイスを開く」で開きます — 例: ハブの当たり判定(机の上のノートPC)。",
