"Apps": "アプリ",
"Reihenfolge wie auf dem Gerät. Symbol: Emoji oder eigenes Bild. Mit 🔒 erscheint eine App erst, wenn ihre Bedingungen erfüllt sind.": "デバイスと同じ順番。アイコン: 絵文字か独自画像。🔒 のアプリは条件を満たしたときだけ表示されます。",
"— Bild —": "— 画像 —",
"App erst zeigen, wenn …": "アプリの表示条件 …",
"Inhalt …": "内容 …",
"Das System dazu ist ausgeschaltet – die App wird nicht angezeigt.": "ゲームシステムがオフです — アプリは表示されません。",
"Notizen": "メモ",
"App hinzufügen …": "アプリを追加 …",
"System aus": "システムオフ",
"Im Spiel öffnen": "ゲーム内で開く方法",
"Knopf oben rechts, Taste oder Pausenmenü (siehe „Gerät“). In der Story oder im Hub: Aktion „📱 Gerät öffnen“, z. B. an einem Hub-Objekt (Hitbox) – optional direkt in einer App oder einem Chat. Eingebaute Apps öffnen ihren Bildschirm und kehren danach zum Gerät zurück.": "右上のボタン、キー、ポーズメニュー(「デバイス」参照)。ストーリーやハブでは: アクション「📱 デバイスを開く」、例: ハブオブジェクト(当たり判定)— アプリやチャットを直接開くことも可能。内蔵アプリは画面を開き、その後デバイスに戻ります。",
"Zu den Nachrichten →": "メッセージへ →",
"Vorschau (klickbar)": "プレビュー(クリック可能)",
"In der Vorschau sind alle Unterhaltungen schon angekommen. Eingebaute Apps und Aktionen laufen erst im Spiel.": "プレビューではすべての会話が届いた状態です。内蔵アプリとアクションはゲーム内でのみ動作します。",
"Eine eigene App zeigt eine Seite (z. B. Notizen, eine E-Mail, eine Webseite, ein Foto) und/oder führt Aktionen aus. Mit „➜ Zu Szene oder Hub wechseln“ schließt sich das Gerät und die Szene startet.": "独自アプリはページ(例: メモ、メール、Webサイト、写真)を表示し、アクションを実行します。「➜ シーンまたはハブへ」でデバイスが閉じてシーンが始まります。",
"Titel der Seite": "ページタイトル",
"Beim Öffnen ausführen": "開いたときに実行",
"Chats bleiben über alle Szenen erhalten. Eine Unterhaltung kommt automatisch an (sobald ihre Bedingungen stimmen) oder per Aktion „💬 Nachricht schicken“. Zeilen mit 🔒 kommen nur, wenn ihre Bedingungen erfüllt sind – so bekommt jede Route ihre eigene Version. Antworten wählt der Spieler; sie können Aktionen ausführen und zur nächsten Unterhaltung führen.": "チャットはすべてのシーンで保持されます。会話は自動で(条件を満たしたらすぐ)、またはアクション「💬 メッセージを送る」で届きます。🔒 の行は条件を満たしたときだけ届くので、ルートごとに違う内容になります。プレイヤーが返信を選び、返信はアクションを実行したり次の会話へつながったりします。",
"Kein Gerät hat die App „Nachrichten“. Unter „Geräte“ hinzufügen.": "「メッセージ」アプリを持つデバイスがありません。「デバイス」で追加してください。",
"Meldung bei neuer Nachricht (Klick öffnet den Chat)": "新着メッセージの通知(クリックでチャットを開く)",
"Ton bei neuer Nachricht": "新着メッセージの音",
"— wie Beziehungs-Meldung —": "— 関係の通知と同じ —",
"Chat-Zeilen in der Timeline (Dialog „Als Handy-Nachricht zeigen“) landen ebenfalls im Verlauf, wenn der Sprecher ein Kontakt ist – und ältere Nachrichten erscheinen dort darüber.": "タイムラインのチャット行(セリフ「スマホのメッセージとして表示」)も、話者が連絡先なら履歴に追加され、古いメッセージはその上に表示されます。",
