"Geräte & Nachrichten": "デバイスとメッセージ",
"Handy oder Computer im Spiel mit Apps (Nachrichten, Inventar, Galerie …). Chats bleiben über Szenen erhalten, mit Routen-Varianten und Antworten zum Auswählen.": "アプリ(メッセージ、インベントリ、ギャラリー …)を備えたゲーム内のスマホやパソコン。チャットはシーンをまたいで保持され、ルート別の内容や選べる返信もあります。",
