"Tipp: Die Auswahl lässt sich auch direkt auf der Bühne mit der Maus verschieben.": "ヒント: 選択肢はステージ上でマウスで直接ドラッグすることもできます。",
"Position und Breite dieser Auswahl auf alle anderen Auswahlen im Projekt übertragen": "この選択肢の位置と幅をプロジェクト内の他のすべての選択肢にコピー",
