"Mit Gegenstand leichter": "アイテムで簡単に",
"Gegenstand: Fläche + % / Tempo − %": "アイテム: 範囲 + % / 速度 − %",
"Titel (leer = „Im richtigen Moment drücken!“)": "タイトル(空 =「タイミングよく押せ!」)",
"Bild Scheibe": "文字盤の画像",
"Bild Zeiger": "針の画像",
"Scheibe": "文字盤",
"Zeiger": "針",
"Im richtigen Moment drücken!": "タイミングよく押せ!",
"Leertaste, Enter oder Klick": "スペース、Enter、またはクリック",
"Treffer!": "ヒット!",
"Daneben!": "ミス!",
"Perfekt – kein Fehler!": "パーフェクト — ノーミス!",
"Ein Zeiger dreht sich – im richtigen Moment drücken, wenn er in der markierten Fläche steht. Die Fläche springt nach jedem Treffer weiter. Leichter durch Skilltree-Perks, Ausrüstung oder einen Hilfs-Gegenstand.": "針が回転します — 印のついた範囲にある瞬間に押してください。ヒットするたびに範囲が別の場所へ移ります。スキルツリーの特典、装備、補助アイテムで簡単になります。",
"Schwierigkeit, Tempo, Größe der Fläche, Treffer, Fehlversuche, schneller werden, Richtungswechsel, Zeitlimit, Hilfs-Gegenstand, eigene Bilder": "難易度、速度、範囲の大きさ、ヒット、ミス、加速、方向転換、制限時間、補助アイテム、独自画像",
"Sieben Minispiele mit Ergebnis (0–100 % oder geschafft/nicht geschafft): Klick-Reflex, Memory, Puzzle, Kochen & Brauen, Münzwurf, Blütenblätter, Quicktime-Kreis.": "結果(0–100 %または勝ち/負け)を返す7つのミニゲーム: クリック反射、神経衰弱、パズル、料理と調合、コイントス、花占い、クイックタイムサークル。",
"Erscheint auf": "表示先",
"allen Geräten": "すべてのデバイス",
"Unterhaltung „{t}“ ist nur für Geräte ohne App „Nachrichten“ bestimmt – sie wäre nirgends zu lesen.": "会話「{t}」は「メッセージ」アプリのないデバイス専用になっています — どこでも読めません。",
"still (versteckt)": "サイレント(非表示)",
"Keine Meldung und keine Ungelesen-Zahl – der Spieler findet die Nachricht nur, wenn er selbst nachsieht (z. B. versteckte Mails auf einem PC).": "通知も未読数もなし — プレイヤーは自分で探さないと見つけられません(例: PC内の隠しメール)。",
