"Code": "コード",
"z. B. 1234 oder Drache": "例: 1234 または dragon",
"Nur Ziffern = Zahlenfeld, sonst Passwort-Feld. Auch {Platzhalter} einer Variable möglich.": "数字のみ = テンキー、それ以外はパスワード欄。変数の {placeholder} も使えます。",
"Einmal richtig eingeben, danach immer offen": "一度正しく入力すれば以後は常に開く",
