"Ohne Code ist das Gerät nicht gesperrt.": "コードがなければデバイスはロックされません。",
"Prüfen mit der Bedingung „🔓 Gerät entsperrt“. Findet der Spieler den Code in der Story, kann die Aktion „🔓 Gerät entsperren“ ihn auch direkt freischalten.": "条件「🔓 デバイス解除済み」で確認します。プレイヤーがストーリーでコードを見つけたら、アクション「🔓 デバイスを解除」で直接解除できます。",
"Falscher Code": "コードが違います",
"Passwort": "パスワード",
