"Beim Lesen dieser Nachricht ausführen (z. B. Ort freischalten)": "このメッセージを読んだときに実行(例: 場所を解放)",
"Regen, Schnee, Staub, Funken, Blütenblätter oder Glühwürmchen über dem ganzen Hub.": "ハブ全体に雨、雪、ほこり、火花、花びら、ホタル。",
