"Mit 🔒 z. B. Glühwürmchen nur nachts oder Schnee nur im Winter. Wechselt, sobald im Hub Zeit vergeht.": "🔒 で例えば夜だけホタル、冬だけ雪。ハブで時間が進むとすぐに切り替わります。",
"Beim Betreten des Hubs": "ハブに入ったとき",
"Sobald „Nur wenn“ stimmt (auch mitten im Hub)": "「条件」を満たしたらすぐ(ハブにいる間も)",
"Nur einmal": "1回のみ",
"Jedes Mal": "毎回",
"Höchstens … mal": "最大 … 回",
"Einmal pro Tag": "1日1回",
"Gerät „{d}“ nutzt die Taste H – die ist auch „🏠 Zuhause“ bei Welt & Orte. Andere Taste wählen, z. B. P.": "デバイス「{d}」はHキーを使っていますが、これは「ワールドと場所」の「🏠 自宅」と同じです。別のキー(例: P)を選んでください。",
"Aus der Liste nehmen (der Ordner bleibt)": "リストから削除(フォルダーは残る)",
"Desktop-Version herunterladen": "デスクトップ版をダウンロード",
"Die Windows-Version eines Spiels lässt sich nur mit der Desktop-Version der Engine bauen. Im Browser: Web-Export (ZIP, z. B. für itch.io).": "ゲームのWindows版はエンジンのデスクトップ版でのみ作成できます。ブラウザでは: Web書き出し(ZIP、例: itch.io向け)。",
"Ein Projektordner (mit project.json) – Änderungen werden direkt dort gespeichert, wie in der Desktop-Version.": "プロジェクトフォルダー(project.jsonつき)— デスクトップ版と同じく変更はそこに直接保存されます。",
"In der ZIP-Datei ist kein Projekt (project.json fehlt).": "ZIPファイルにプロジェクトが含まれていません(project.jsonがありません)。",
"In diesem Projekt fehlt die project.json.": "このプロジェクトには project.json がありません。",
"Läuft ohne Installation. Projekte werden in diesem Browser gespeichert – lade sie über „Projekt ▾ → Als ZIP herunterladen“ als Sicherung herunter.": "インストール不要で動きます。プロジェクトはこのブラウザに保存されます —「プロジェクト ▾ → ZIPでダウンロード」でバックアップしてください。",
"Noch keine Projekte in diesem Browser.": "このブラウザにはまだプロジェクトがありません。",
