"Dart, Billard und Spielautomat – mit Computer-Gegnern, deren Können du einstellst, und eigenen Bildern für Scheibe, Tisch, Kugeln und Walzen.": "ダーツ、ビリヤード、スロット – 強さを決められるCPU対戦相手と、ボード・台・球・リールの自作画像。",
