"Die Spiele startest du mit den Aktionen „Spielhalle: Dart“, „Spielhalle: Billard“ und „Spielhalle: Spielautomat“ – z. B. an einem Hub-Objekt (Dartscheibe in der Taverne) oder in einer Antwort. Wie bei allen Minispielen kannst du dort eine Szene für Sieg und Niederlage wählen.": "ゲームはアクション「ゲームセンター：ダーツ」「ゲームセンター：ビリヤード」「ゲームセンター：スロットマシン」で始めます（例：ハブのオブジェクト＝酒場のダーツボード、または選択肢）。他のミニゲームと同じく、勝ち・負けのシーンを選べます。",
