"🎱 Billard": "🎱 ビリヤード",
"Das Fadenkreuz schwebt über die Scheibe – im richtigen Moment klicken. Spielarten: 301 oder 501 (von oben auf 0, auf Wunsch mit einem Doppel zum Schluss) oder „höchste Punktzahl nach X Runden“. Mit Gegner abwechselnd je 3 Pfeile, allein gegen eine Punktzahl. Scheibe, Pfeil, Fadenkreuz und Hintergrund lassen sich durch eigene Bilder ersetzen (an der Aktion oder als Standard unter Design → Spielsysteme). Bei einer eigenen Scheibe gibst du an, wie groß der Doppel-Ring im Bild ist – danach wird gezählt.": "照準がボードの上を漂います。タイミングよくクリック。ルール：301か501（0まで減らす、最後をダブルにもできる）または「Xラウンド後の最高得点」。対戦は3本ずつ交代、ひとりなら目標点に挑戦。ボード・矢・照準・背景は自分の画像に替えられます（アクションか、デザイン → ゲームシステムの標準）。自作ボードでは画像内のダブルリングの大きさを指定し、それで得点を数えます。",
"Dart allein ausprobieren": "ダーツをひとりで試す",
"Mit der Maus zielen, Maustaste drücken = anlegen, zurückziehen und nach vorn schwingen = stoßen. Je schneller der Schwung, desto härter der Stoß (Loslassen stößt mit der Kraft des Zurückziehens). Spielarten: 8-Ball (Volle/Halbe, zum Schluss die 8) oder „wer mehr Kugeln versenkt“. Tisch, Tuch, Queue und jede Kugel lassen sich gestalten – Kugeln 1–15 als Standard unter Design → Spielsysteme → Billard.": "マウスで狙い、ボタンを押す＝構える、引いて前に振る＝ショット。振りが速いほど強いショット（離すと引いた分の強さで打つ）。ルール：8ボール（ソリッド/ストライプ、最後に8番）または「多く落とした方が勝ち」。台・ラシャ・キュー・各球をデザインでき、1〜15番球の標準はデザイン → ゲームシステム → ビリヤード。",
"Billard allein ausprobieren": "ビリヤードをひとりで試す",
