"Unter 100 % verliert man auf Dauer (wie bei echten Automaten, meist 85–95 %), über 100 % gewinnt man. Ändern mit der Häufigkeit der Symbole und den Gewinnen.": "100%未満だと長く遊ぶほど負け（本物のマシンは大抵85〜95%）、100%超だと勝ち。絵柄の出やすさと配当で調整します。",
