"Rad mit der Maus drehen (oder Mausrad, Pfeiltasten). Bei der richtigen Zahl einrasten – Mitte anklicken oder Enter.": "マウスでダイヤルを回す（ホイール・矢印キーも可）。正しい数で確定＝中央をクリックかEnter。",
