"Tresor mit Drehrad, Tastenfeld oder Zahlenschloss mit Rädchen. Der Code kann fest sein, aus einer Variable kommen (dann findet man ihn in der Geschichte) oder zufällig – auch zufällig in eine Variable, die du später im Text zeigst.": "ダイヤル、テンキー、数字ホイール錠の金庫。コードは固定、変数から（物語の中で見つけられる）、またはランダム。ランダムを変数に入れて後で文中に出すこともできます。",
"Art, Code, Zahlen auf dem Rad, Hilfe (Klicken abhören oder Farben), Versuche, Zeitlimit, Hilfs-Gegenstand, Bilder für Tür, Rad und Inhalt": "種類、コード、目盛りの数、補助（カチッ音か色）、試行回数、制限時間、補助アイテム、扉・ダイヤル・中身の画像",
"Teile drehen, bis die Leitung von links nach rechts durchgeht – als Rohre mit Wasser, Kabel mit Strom oder magische Runen. Jedes Feld ist zufällig und immer lösbar.": "左から右までつながるようにピースを回す。水道管、電線、魔法のルーンから選択。盤面は毎回ランダムで必ず解けます。",
"Größe, Aussehen, Zeitdruck, Drehungen, eigene Bilder für die Teile": "サイズ、見た目、時間制限、回転数、ピースの自作画像",
"Neun Minispiele. Du startest sie über „+ Aktion“ → „Minispiele: …“ – in einer Antwort, an einem Hub-Objekt, in einem Dialog oder als Minispiel eines Jobs. Einstellungen und Bilder wählst du direkt an der Aktion. Jedes Spiel liefert ein Ergebnis von 0–100 % (Feld „Ergebnis in“ → Variable).": "ミニゲーム9種。「＋アクション」→「ミニゲーム：…」で開始（選択肢、ハブのオブジェクト、会話、仕事のミニゲーム）。設定と画像はアクションで直接選びます。結果は0〜100%（「結果の保存先」→変数）。",
