"Die Spiele startest du mit den Aktionen „Spielhalle: Dart“, „Spielhalle: Billard“, „Spielhalle: Blackjack“ und „Spielhalle: Spielautomat“ – z. B. an einem Hub-Objekt (Dartscheibe in der Taverne) oder in einer Antwort. Wie bei allen Minispielen kannst du dort eine Szene für Sieg und Niederlage wählen.": "ゲームはアクション「ゲームセンター：ダーツ」「ゲームセンター：ビリヤード」「ゲームセンター：ブラックジャック」「ゲームセンター：スロットマシン」で始めます（例：ハブのオブジェクト＝酒場のダーツボード、または選択肢）。他のミニゲームと同じく、勝ち・負けのシーンを選べます。",
"🎲 Dart, Billard, Blackjack": "🎲 ダーツ、ビリヤード、ブラックジャック",
"🃏 Blackjack": "🃏 ブラックジャック",
"Näher an 21 als der Croupier, ohne drüber zu kommen. Ziehen, Stehen, Verdoppeln und Teilen; Blackjack zahlt 3:2 (oder 6:5). Einsatz in einer Währung deines Spiels oder mit Spielgeld. Als Croupier kannst du einen Gegner wählen – dann erscheinen sein Name, Bild und seine Sprüche. Mit „Tipps“ (oder einem Gegenstand bzw. Perk) zeigt das Spiel den besten Zug nach der Grundstrategie.": "21を超えずにディーラーより21に近づける。ヒット、スタンド、ダブル、スプリット。ブラックジャックは3:2（または6:5）。ゲーム内通貨か遊び用チップで賭けます。対戦相手をディーラーにすると名前・画像・セリフが出ます。「ヒント」（またはアイテム・パーク）で基本戦略の最善手を表示。",
