"Import abgebrochen – es wurde nichts gespeichert.": "インポートを中止しました – 何も保存されていません。",
"Ein Social Media im Spiel: Kontakte posten Beiträge mit Text und Bild, andere Figuren liken und kommentieren. Ein Beitrag erscheint automatisch, sobald seine Bedingungen stimmen, oder nur per Aktion „📸 Beitrag posten“ (z. B. nach einer Entscheidung, an einem Ort oder nach einem Minispiel). Der Spieler kann liken und mit vorbereiteten Antworten kommentieren.": "ゲーム内SNS：連絡先がテキストや画像を投稿し、他のキャラがいいねやコメントをします。投稿は条件を満たすと自動で表示されるか、アクション「📸 投稿する」でのみ表示されます（選択の後、場所、ミニゲームの後など）。プレイヤーはいいねや用意された返信でコメントできます。",
