"Für Szenen, in denen eine Figur streamt: Nachrichten erscheinen nacheinander in der Chatleiste. Starte den Chat mit der Aktion „📺 Live-Chat“ (z. B. im ersten Schritt der Szene). Antworten kann der Spieler anklicken – mit Aktionen dahinter.": "キャラが配信するシーン向け：メッセージがチャット欄に順番に表示されます。アクション「📺 ライブチャット」で開始（例：シーンの最初のステップ）。プレイヤーは返信をクリックでき、アクションも実行できます。",
