"Tipp: Kiefer-Größe und -Bereich so wählen, dass die rosa Fläche Unterlippe und Kinn umfasst – sie klappt beim Öffnen um das Gelenk.": "ヒント：ピンクの範囲が下唇とあごを含むように顎の大きさと範囲を設定 – 開くとき関節を中心に回ります。",
"Objekt für den Mund von": "次のキャラの口用オブジェクト",
"Setze Griff und Spitze. Die Breite misst die Engine selbst aus dem Bild – an jeder Stelle des Objekts.": "持ち手と先端を設定。幅はエンジンが画像から自動で測ります – オブジェクトのどの位置でも。",
