"Setze linken und rechten Mundwinkel und das Kinn. Kommt ein Objekt auf die Mundmitte zu, senkt sich der Unterkiefer so weit, wie das Objekt dort breit ist. Was schon im Mund ist, sieht man nur noch durch die Öffnung.": "左右の口角とあご先を設定。オブジェクトが口の中央に来ると、その幅だけ下顎が下がります。口の中に入った部分は開口部からしか見えません。",
