"Gebäude auf dem Bild an ihren Platz ziehen. Ein Gebäude anklicken, dann lässt sich seine Größe einstellen. Am schönsten mit Gebäudebildern mit durchsichtigem Hintergrund.": "建物を画像上の位置へドラッグ。クリックするとサイズを調整できます。背景透過の建物画像が最適です。",
