"Wie stark Preise und Erträge mit jeder Stufe wachsen. Vorlagen nach bekannten Idle-Spielen – danach frei anpassbar. Einzelne Gebäude können eine eigene Kurve haben.": "レベルごとに価格と収益がどれだけ増えるか。有名な放置ゲームのテンプレート – 後から自由に調整可。建物ごとに独自のカーブも設定できます。",
"Bei Vorlagen mit festem Faktor auch „× pro Stufe“ aller Gebäude setzen": "固定係数のテンプレートでは全建物の「レベルごとの×」も設定",
"Preise": "価格",
"Potenz": "べき指数",
"+ % vom Grundpreis je Stufe": "レベルごとに基本価格の＋%",
"Bremse (0,3–1)": "減速（0.3–1）",
"× je Stufe": "レベルごとに×",
"Abflachung (0,3–1)": "頭打ち度（0.3–1）",
"Sprünge (Ertrag × ab Stufe):": "ジャンプ（レベル以降 収益×）：",
"Sprung": "ジャンプ",
"Verlauf für": "カーブ対象",
"Klassisch": "クラシック",
"Preise × Faktor pro Stufe, Gewinn wächst gleichmäßig (bisheriges Verhalten).": "価格はレベルごとに×係数、利益は均等に増加（従来の動作）。",
"Preise × 1,07–1,15, Gewinn gleichmäßig – dazu ×2-Sprünge bei Stufe 25, 50, 100, 200 …": "価格×1.07–1.15、利益は均等 – さらにレベル25, 50, 100, 200 … で×2。",
"Jeder Kauf 15 % teurer, jedes Gebäude bringt gleich viel dazu.": "購入ごとに15%高くなり、各建物は同じだけ加算。",
"Gemächlich": "のんびり",
"Preise steigen nur im Quadrat statt exponentiell – auch nach vielen Stufen noch gut spielbar.": "価格は指数ではなく二乗で増加 – 多くのレベル後も遊びやすい。",
"Exponentiell, aber die Steigerung lässt mit der Zeit nach.": "指数的だが、増加は徐々に緩やかに。",
"Story (linear)": "ストーリー（線形）",
"Jede Stufe kostet gleich viel mehr – planbar, gut für kurze Aufbau-Phasen in der Geschichte.": "レベルごとに同じだけ高くなる – 予測しやすく、物語中の短い構築パートに最適。",
"Schneeball": "雪だるま",
"Gewinne wachsen selbst exponentiell mit – fühlt sich schnell und mächtig an.": "利益自体も指数的に増加 – 速く強力に感じる。",
