"🙂 Ausdruck": "🙂 表情",
"🙂 Gesicht einrichten (Ausdrücke, Blinzeln, Mund)": "🙂 顔を設定（表情・まばたき・口）",
"🙂 Gesicht: Ausdruck": "🙂 顔：表情",
"+ Erste Kulisse anlegen": "+ 最初のセットを作成",
