"Neue Kulisse": "新しいセット",
"Kulisse": "セット",
"Kulissen": "セット",
"Kulissen-Raum": "3Dセット",
"Kulissen-Raum (3D)": "3Dセット",
"Kulisse bearbeiten": "セットを編集",
"Lege links eine Kulisse an.": "左側でセットを作成してください。",
"Noch keine Kulisse. Im Reiter „Kulissen“ baust du Räume aus PNG-Flächen.": "まだセットがありません。「セット」タブでPNGの面から部屋を作れます。",
"— keine, normales Bild —": "— なし（通常の画像）—",
"Baue einen echten Raum aus PNG-Flächen: Rückwände, Böden, Decken, Zwischenwände, Balken und Möbel. Die Kamera schaut mit Perspektive hinein – Parallax entsteht von selbst. ": "PNGの面で本物の部屋を作ります：奥の壁、床、天井、仕切り壁、梁、家具。カメラが遠近法で覗き込むので、パララックスは自然に生まれます。",
"Fenster sind einfach durchsichtige Stellen im Wand-PNG: man sieht hinaus, und das Fensterlicht fällt hindurch. ": "窓は壁PNGの透明な部分です。外が見え、窓の光が差し込みます。",
"Eine Kulisse wählst du danach am Hintergrund-Clip einer Szene oder am Hub als Hintergrund.": "その後、シーンの背景クリップやハブの背景としてセットを選びます。",
