"Rand-Scrollen in dieser Szene (Maus an den Bildrand)": "このシーンで端スクロール（マウスを画面端へ）",
"Scroll-Tempo": "スクロール速度",
"Gescrollt wird im Hub immer, in Szenen nur mit dem Haken „Rand-Scrollen“ am Hintergrund-Clip. Ist „bis X“ nicht größer als „von X“, steht die Kamera still.": "ハブでは常にスクロールします。シーンでは背景クリップの「端スクロール」がオンのときだけです。「終了 X」が「開始 X」より大きくなければカメラは動きません。",
"Licht und Schatten berechnen": "光と影を計算",
"Tageszeit, wenn die Szene keine vorgibt": "シーンが指定しないときの時間帯",
"Tipps": "ヒント",
"Pro Raumwand ein eigenes PNG (etwa 2000–4000 px breit) statt eines Riesenbilds. Fenster und Türen: Stellen im PNG durchsichtig machen. Halbdurchsichtig = Glas.": "巨大な1枚ではなく、壁ごとに1枚のPNG（幅2000〜4000px程度）。窓とドア：PNGのその部分を透明に。半透明＝ガラス。",
"Figuren und Hub-Objekte stehen auf der Ebene Z = 0. Was weiter vorne liegt (Balken, Pflanzen), wird vor den Figuren gezeichnet.": "キャラクターとハブのオブジェクトはZ＝0の面に立ちます。それより手前のもの（梁、植物）はキャラクターの前に描かれます。",
"Scheint von draußen durch alle Fenster. Wände, Böden und Decken sind Hindernisse, Möbel und Figuren nicht. Hat eine Rückwand eine Jalousie, fällt das Licht in Streifen.": "すべての窓から外の光が差し込みます。壁・床・天井は遮りますが、家具とキャラクターは遮りません。奥の壁にブラインドがあれば光は縞模様になります。",
"Lichtstrahlen in der Luft": "空中の光の筋",
"Farbe und Richtung nach Tageszeit": "時間帯に応じた色と向き",
"Nach Tageszeit: morgens flach von links und warm, mittags steil, abends orange von rechts, nachts schwaches Mondlicht.": "時間帯に応じて：朝は左から低く暖かく、昼は高く、夕方は右からオレンジ、夜は弱い月明かり。",
"Eingeschaltet bei": "点灯する時間帯",
"Wände werfen Schatten": "壁が影を落とす",
"Die Lampe schaltet sich je nach Tageszeit der Szene automatisch ein oder aus.": "ランプはシーンの時間帯に応じて自動で点いたり消えたりします。",
"Um aktuelle Ansicht legen": "現在のビューの周りに配置",
"Musik beim Betreten": "入ったときの音楽",
"Geräusch-Schleife (Atmo)": "ループ音（環境音）",
"Fährt die Kamera in diese Zone (Rand-Scrollen im Hub oder in der Szene), wechselt die Musik und die Atmo läuft in Schleife.": "カメラがこのゾーンに入ると（ハブやシーンの端スクロール）、音楽が変わり環境音がループします。",
"Bild (PNG)": "画像（PNG）",
"Eigene Bilder je Tageszeit (optional)": "時間帯ごとの画像（任意）",
"Ohne eigenes Bild wird automatisch eingefärbt oder beleuchtet. Praktisch für den Himmel: Sterne, Sonne, Abendrot.": "専用の画像がなければ自動で色付けまたは照明されます。空に便利：星、太陽、夕焼け。",
"Höhe nach Bild": "画像に合わせた高さ",
"Dichte": "密度",
"Eine Partikel-Fläche ist ein Fenster, in dem es regnet oder schneit. In die Tiefe gestellt, bewegt sie sich beim Scrollen mit dem passenden Parallax. Für mehr Tiefe zwei Flächen hintereinander.": "パーティクル面は雨や雪が降る窓です。奥行きに置くとスクロール時に適切なパララックスで動きます。より奥行きを出すには2枚を前後に置きます。",
"Z · Tiefe": "Z・奥行き",
