"Jalousie an den Fenstern dieser Wand": "この壁の窓にブラインド",
"Lamellen-Abstand": "スラットの間隔",
"Öffnung": "開き具合",
"Außenwand (wird nur von innen beleuchtet)": "外壁（内側からのみ照明）",
"Vom Licht der Kulisse beleuchten": "セットの光で照らす",
"Steht der Balken genau auf der Tiefe der Wandkante, bewegt er sich beim Scrollen exakt mit und verdeckt die dünne Kante.": "梁が壁の縁と同じ奥行きにあれば、スクロール時に一緒に動き、細い縁を隠します。",
"Um 90° gedreht. Beim Scrollen sieht man ihre Seitenfläche wie bei einem Puppenhaus. Für Licht ist sie ein Hindernis, durch eine durchsichtige Tür kommt es durch.": "90°回転。スクロールすると人形の家のように側面が見えます。光を遮りますが、透明なドアからは光が通ります。",
"Möbel werden beleuchtet, werfen aber keinen Schatten auf Wände.": "家具は照らされますが、壁に影は落としません。",
"Hintergründe werden nicht beleuchtet, aber nach Tageszeit eingefärbt – oder du gibst eigene Bilder je Tageszeit an.": "背景は照明されませんが、時間帯に応じて色付けされます。時間帯ごとの画像を指定することもできます。",
"An Wandkante einrasten": "壁の縁に合わせる",
"Im Hub scrollt die Kulisse, wenn die Maus an den Bildrand geht. Hub-Objekte wandern mit. Tageszeit, Licht und Kamera kommen aus der Kulisse und aus dieser Szene.": "ハブではマウスが画面端に来るとセットがスクロールします。ハブのオブジェクトも一緒に動きます。時間帯・光・カメラはセットとこのシーンから決まります。",
"Kamera-Schwenks dieser Szene fahren durch den Raum, mit echter Tiefe. Die Tageszeit oben schaltet Lampen und Fensterlicht um.": "このシーンのカメラのパンは本物の奥行きで部屋の中を進みます。上の時間帯でランプと窓の光が切り替わります。",
